#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

#
# Tailscale spec test (INT-666). One check per assumption the Tailscale (HI)
# connector makes about Tailscale's API and policy engine (the inventory's
# checks, by their A-numbers), run against a throwaway lab tailnet. Each check
# records PASS, FAIL, SKIP (setup missing) or HUMAN (a person did something
# and answered).
#
#   services/p0-connector-tailscale/scripts/admin-test.sh --help
#
# It uses two OAuth clients. The connector's client holds exactly the
# connector's scopes. The admin client is the test's own: it writes test
# postures and posture-gated grants into the lab policy file, which the
# connector never does.
#
# Inputs come from ENV_FILE (scripts/admin-test.env.example lists them).
# Secrets are read hidden, held in shell variables only, sent to curl on its
# stdin config, cut from every logged body, and never written anywhere.
# Every write snapshots first and is undone after its check and again on any
# exit, Ctrl-C included.

API="https://api.tailscale.com/api/v2"
CONSOLE="https://login.tailscale.com/admin"
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

# The connector's scopes (src/tailscale/scopes.ts): what its credential must
# hold (REQUIRED_SCOPES), and what its read and write tokens ask for.
REQUIRED_SCOPES="policy_file:read users:read devices:core:read devices:posture_attributes devices:routes:read services:read"
READ_SCOPES="users:read devices:core:read devices:routes:read services:read policy_file:read devices:posture_attributes:read"
WRITE_SCOPES="devices:posture_attributes"

# The admin client's scopes. It mints READ_SCOPES for the test's own reads,
# and ADMIN_WRITE_SCOPES to write the lab policy file, so it holds
# policy_file, which the connector refuses.
ADMIN_REQUIRED="policy_file users:read devices:core:read devices:posture_attributes devices:routes:read services:read"
ADMIN_WRITE_SCOPES="policy_file devices:core:read devices:posture_attributes"

# The riskiest assumptions: a FAIL on any of these is printed first.
RISKY="A03 A48 A49 A50 A14"

# ── Arguments ─────────────────────────────────────────────────────────────

usage() {
  cat <<'EOF'
Tailscale spec test (INT-666): checks every Tailscale API behaviour the
Tailscale connector relies on, against a throwaway lab tailnet.

Usage: admin-test.sh --setup     fill in the env file (run this first)
       admin-test.sh [options]  run the checks

  --setup           walk through creating the two OAuth clients, then find
                    the tailnet, devices and routes through the API and
                    write them to the env file; with --dry-run, print the
                    calls instead
  --env-file PATH   inputs file (default .env in the current folder); the
                    ENV_FILE variable works too
  --only IDS        run only these checks, such as --only A48 or --only A48,A60
  --area NAMES      run only these areas, such as --area posture or --area oauth,errors
  --list            list every check with its area and kind, then exit
  --dry-run         print each call instead of making it; asks nothing, writes nothing
  --unattended      run without a person: skips human-only checks, marks any
                    check that needed a person as SKIP, answers yes to gates
  --confirm-lab ID  confirm the lab tailnet without typing it (needed with
                    --unattended)
  -h, --help        this help

Areas: oauth federated errors policy posture devices rate revoke

Results go to spec-results-<timestamp>.md next to the env file, ready to
paste into INT-666. Run --setup first to fill in the env file
(scripts/admin-test.env.example lists what it holds).
EOF
}

die() {
  printf '%s\n' "$*" >&2
  exit 2
}

DRY_RUN=0
UNATTENDED=0
CONFIRM_LAB=""
NEEDED_PERSON=0
SETUP=0
LIST=0
ONLY=""
AREA_SEL=""
while [[ $# -gt 0 ]]; do
  case "$1" in
    --only) [[ $# -ge 2 ]] || die "--only needs a check ID, such as A48"; ONLY="$2"; shift 2 ;;
    --only=*) ONLY="${1#*=}"; shift ;;
    --area) [[ $# -ge 2 ]] || die "--area needs an area name, such as posture"; AREA_SEL="$2"; shift 2 ;;
    --area=*) AREA_SEL="${1#*=}"; shift ;;
    --env-file) [[ $# -ge 2 ]] || die "--env-file needs a path"; ENV_FILE="$2"; shift 2 ;;
    --env-file=*) ENV_FILE="${1#*=}"; shift ;;
    --list) LIST=1; shift ;;
    --dry-run) DRY_RUN=1; shift ;;
    --unattended) UNATTENDED=1; shift ;;
    --confirm-lab) [[ $# -ge 2 ]] || die "--confirm-lab needs the Tailnet ID"; CONFIRM_LAB="$2"; shift 2 ;;
    --confirm-lab=*) CONFIRM_LAB="${1#*=}"; shift ;;
    --setup) SETUP=1; shift ;;
    -h | --help) usage; exit 0 ;;
    *) printf 'Unknown option: %s\n\n' "$1" >&2; usage >&2; exit 2 ;;
  esac
done
ONLY="$(printf '%s' "$ONLY" | tr '[:lower:]' '[:upper:]' | tr ',' ' ')"
AREA_SEL="$(printf '%s' "$AREA_SEL" | tr '[:upper:]' '[:lower:]' | tr ',' ' ')"

dry() { [[ "$DRY_RUN" == 1 ]]; }

# ── The checks ────────────────────────────────────────────────────────────

C_IDS=()
C_AREAS=()
C_KINDS=()
C_TAGS=()
C_CLAIMS=()

# def ID AREA KIND TAG CLAIM registers one check. KIND is read (safe read),
# write (reversible write) or human (human-only), as the inventory has it.
def() {
  C_IDS+=("$1")
  C_AREAS+=("$2")
  C_KINDS+=("$3")
  C_TAGS+=("$4")
  C_CLAIMS+=("$5")
}

def A01 oauth read "" 'A token mint returns a tskey token, expires_in 3600 and scope'
def A02 oauth read "" 'A mint with no scope carries and lists every scope the client holds'
def A03 oauth read "" 'A subset mint works, including :read of a write-held scope (READ_SCOPES)'
def A04 oauth read "" 'A mint asking for a scope the client lacks fails with 400'
def A06 oauth read "" 'A wrong secret or unknown client ID answers 400/401 with an OAuth error body'
def A07 oauth read "" 'A token stays usable for its whole hour'
def A08 oauth human "" "A deleted client's token answers 401, and a fresh mint is refused"
def A09 oauth human INT-666 'OAuth client secret rotation means a new client and client ID'
def A10 oauth read "" 'all covers every scope, and all:read every :read scope'
def A11 federated human "" 'The token exchange takes client_id and jwt only'
def A12 federated human "" "The exchange's scope lists the identity's configured scopes"
def A13 federated human "" 'The default audience is api.tailscale.com/<client ID>'
def A14 federated human "" 'An AWS ES384 300 s token is accepted, with sub the role ARN'
def A15 federated human "" 'A GCP ID token has iss accounts.google.com, sub the unique ID, and is accepted'
def A16 federated read "" 'A garbage or untrusted JWT is refused with 400/401/403'
def A17 errors read INT-666 'A mistyped Tailnet ID gets 404, not 403'
def A18 errors read "" '"-" names the own tailnet; the DNS name is never a Tailnet ID'
def A19 errors read "" 'A missing scope gets 403 with a message'
def A20 errors read "" "A device that isn't on the tailnet gets 404 on the device endpoints"
def A21 errors read "" 'Every non-2xx body is {message}, or {error, error_description} from the token endpoints'
def A22 errors read "" 'No API path answers with a redirect'
def A25 errors write "" 'A 429 comes with Retry-After in seconds, or none'
def A26 errors read "" '5xx answers are JSON {message} or plain text'
def A27 errors write "" 'A plan without custom attributes refuses an attribute write with 400, 402 or 403'
def A28 errors read "" 'Each call answers within 10 seconds'
def A32 policy read "" 'GET /acl as JSON returns a plain JSON object'
def A35 policy write "" 'Section and field names are case-insensitive'
def A46 posture write "" 'Attribute keys: custom:, then letters, digits, _ and :, 128 characters at most'
def A47 posture write "" 'Keys are unique case-insensitively, and a key type is fixed by its first write'
def A48 posture write "" 'The batch PATCH sets and deletes in one call, null deletes, all or nothing'
def A49 posture write "" 'An expiry with milliseconds is accepted and read back as the same instant'
def A50 posture write INT-666 'An attribute whose expiry has passed is accepted, or refused with 400'
def A51 posture human "" 'Tailscale removes an expired attribute within minutes, and the posture stops matching'
def A52 posture human "" 'Deleting the key stops the posture matching within seconds'
def A53 posture write "" "DELETE of a key that isn't set gets 404"
def A54 posture write "" 'A devices:posture_attributes token alone reads and writes attributes'
def A55 posture write "" 'The attribute endpoints work on a tagged device'
def A56 posture write "" "An attribute write's comment is accepted up to 200 characters"
def A57 posture read "" 'posture:p0_<name> with _ is a valid posture name'
def A58 posture read INT-666 'Posture names in srcPosture match case-sensitively'
def A59 posture read "" 'custom:p0_x == true is valid in the array and the {assertions} forms'
def A60 posture human "" 'A custom attribute plus srcPosture gates traffic end to end'
def A61 posture human INT-666 'defaultSrcPosture also gates ssh rules and legacy acls'
def A62 posture human INT-666 'An entry with srcPosture [] or null takes defaultSrcPosture'
def A63 posture human "" 'A srcPosture list passes when any one posture in it passes'
def A64 posture read "" 'srcPosture takes only posture: names, not inline assertions'
def A65 posture human "" "Postures don't restrict traffic from behind subnet routers"
def A66 posture write "" "A policy can't make a custom:p0_ key settable by the node itself"
def A67 devices read "" "An untagged device's user is its owner's loginName; a tagged device carries tags"
def A68 devices read "" 'The ?user= filter matches the login exactly, case-sensitively'
def A69 devices read "" "A device's name is its MagicDNS name, in the tailnet's DNS name"
def A70 devices read "" 'isExternal is true for a shared-in device, whose name is in another domain'
def A71 devices read "" 'Node IDs are letters and digits, at most 64, and /device/{nodeId} takes them'
def A72 devices read "" 'devices?fields=all carries tags, addresses and routes; the default leaves routes out'
def A73 devices read "" 'device.tags spell tags exactly as the tagOwners keys'
def A74 devices read "" "Device and user lists don't paginate"
def A75 devices human "" 'A node ID stays with its device when it signs in as another user'
def A82 oauth read "" 'GET /services answers {vipServices: [{name: "svc:..."}]} to services:read'
def A91 rate write "" "P0's call volume doesn't hit a rate limit"
def A92 revoke human "" 'After a revoke, new connections fail within seconds'
def A93 revoke human "" 'Open TCP connections across a revoke: kept or cut'
def A94 revoke human INT-666 'Open Tailscale SSH sessions end at revoke'
def A95 revoke human "" 'A grant takes effect within seconds'

AREAS="oauth federated errors policy posture devices rate revoke"

area_title() {
  case "$1" in
    oauth) printf 'OAuth client credentials' ;;
    federated) printf 'Federated token exchange' ;;
    errors) printf 'Tailnet ID and error codes' ;;
    policy) printf 'The policy file' ;;
    posture) printf 'Postures and device attributes' ;;
    devices) printf 'Devices' ;;
    rate) printf 'Rate limits' ;;
    revoke) printf 'Revoke and grant timing' ;;
  esac
}

kind_name() {
  case "$1" in
    read) printf 'safe read' ;;
    write) printf 'reversible write' ;;
    human) printf 'human-only' ;;
  esac
}

idx_of() {
  local i
  for ((i = 0; i < ${#C_IDS[@]}; i++)); do
    if [[ "${C_IDS[$i]}" == "$1" ]]; then
      printf '%s' "$i"
      return 0
    fi
  done
  return 1
}

in_list() { [[ " $2 " == *" $1 "* ]]; }

# is_selected INDEX: whether --only and --area let this check run.
is_selected() {
  if [[ -n "$ONLY" ]]; then
    in_list "${C_IDS[$1]}" "$ONLY"
  elif [[ -n "$AREA_SEL" ]]; then
    in_list "${C_AREAS[$1]}" "$AREA_SEL"
  else
    return 0
  fi
}

for want in $ONLY; do
  idx_of "$want" >/dev/null || die "Unknown check $want. Run --list to see them."
done
for want in $AREA_SEL; do
  in_list "$want" "$AREAS" || die "Unknown area $want. The areas are: $AREAS"
done

if [[ "$LIST" == 1 ]]; then
  for area in $AREAS; do
    printf '\n%s%s%s (--area %s)\n' "$BOLD" "$(area_title "$area")" "$RESET" "$area"
    for ((i = 0; i < ${#C_IDS[@]}; i++)); do
      [[ "${C_AREAS[$i]}" == "$area" ]] || continue
      is_selected "$i" || continue
      printf '  %s  %-16s %s%s\n' "${C_IDS[$i]}" "$(kind_name "${C_KINDS[$i]}")" \
        "${C_CLAIMS[$i]}" "$([[ -n "${C_TAGS[$i]}" ]] && printf ' [INT-666]')"
    done
  done
  printf '\n'
  exit 0
fi

for tool in curl jq perl; do
  command -v "$tool" >/dev/null 2>&1 || {
    printf 'This test needs %s. Install it (brew install %s) and run it again.\n' "$tool" "$tool"
    exit 1
  }
done

# ── Inputs ────────────────────────────────────────────────────────────────

