  "FED_AWS_CLIENT_ID|kDryRunFedAWS" "FED_AWS_ROLE_ARN|arn:aws:iam::123456789012:role/p0-spec"
  "FED_AWS_SCOPES|" "SPEC_AWS_PROFILE|" "SPEC_AWS_REGION|us-west-2"
