)

# Secrets: read hidden when a check first needs one, never from or to a file.
ADMIN_SECRET=""
PO_SECRET=""
RO_SECRET=""
ALL_SECRET=""
FREE_SECRET=""

if ! dry && [[ -f "$ENV_FILE" ]] && grep -qE '^[A-Z_]*SECRET[A-Z_]*=' "$ENV_FILE"; then
  die "$ENV_FILE holds a *SECRET* line. Remove it: this test reads secrets hidden and never from a file."
fi

for entry in "${ENV_KEYS[@]}"; do
  key="${entry%%|*}"
  value="${!key:-}"
  if [[ -z "$value" ]]; then
    value="$(_existing "$key" || true)"
    value="${value#\"}"
    value="${value%\"}"
  fi
  if [[ -z "$value" ]] && dry; then value="${entry#*|}"; fi
  printf -v "$key" '%s' "$value"
done
[[ -n "$ADMIN_SCOPES" ]] || ADMIN_SCOPES="$ADMIN_REQUIRED"
[[ -n "$PO_SCOPES" ]] || PO_SCOPES="$REQUIRED_SCOPES"
[[ -n "$FED_AWS_SCOPES" ]] || FED_AWS_SCOPES="$REQUIRED_SCOPES"
[[ -n "$FED_GCP_SCOPES" ]] || FED_GCP_SCOPES="$REQUIRED_SCOPES"
[[ "$RATE_BURST" =~ ^[0-9]+$ ]] || RATE_BURST=20
[[ "$TOKEN_WAIT_MINUTES" =~ ^[0-9]+$ ]] || TOKEN_WAIT_MINUTES=50

OUT_DIR="$(dirname "$ENV_FILE")"
RID="$(LC_ALL=C tr -dc 'a-z0-9' </dev/urandom | head -c 6 || true)"
STAMP="$(date -u +%Y%m%dT%H%M%SZ)"
STARTED="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
RESULTS="$OUT_DIR/spec-results-$STAMP.md"
LOG="$OUT_DIR/spec-log-$STAMP.txt"
ORIGINAL="$OUT_DIR/spec-original-policy-$RID.hujson"
WORK="$(mktemp -d)"
chmod 700 "$WORK"
BODY="$WORK/body"
HEADERS="$WORK/headers"
P="$WORK/policy.hujson"
: >"$BODY"
: >"$HEADERS"
if dry; then
  ORIGINAL="$WORK/original.hujson"
  LOG="/dev/null"
fi

# Everything this run names starts with its run ID, within the connector's
# naming rules (posture:p0_<name>, custom:p0_<name>, lower case).
PST="posture:p0_spec$RID"
KEY="custom:p0_spec$RID"
COMMENT="P0 spec test $RID"

# ── State ─────────────────────────────────────────────────────────────────

ST=000          # the last call's HTTP status
SECS=0          # and its time in seconds
TOKEN=""
TOKEN_WHY=""
SECRETS_LIST="" # every secret and token seen, one per line, cut from output
CALLS=0
MAX_SECS=0
MAX_SECS_WHAT=""
N_3XX=0
LIST_3XX=""
N_429=0
RA_SEEN=""
RA_BAD=""
N_5XX=0
LIST_5XX=""
N_ERR=0
BAD_ERR=""
SECRET_ECHO=""
POLICY_DIRTY=0
POLICY_BROKEN=0
LAST_WRITE_ETAG=""
ORIG_ETAG=""
PETAG=""
SNAPSHOT_DONE=0
ATTRS=()          # DEVICE|KEY pairs this run may have set
BASELINE=""
REVOKE_DONE=0
DEFERRED=""
R_IDS=()
R_RES=()
R_NOTES=()
RESULTS_WRITTEN=0
CUR_ID=""

# ── Output and redaction ──────────────────────────────────────────────────

now() { date +%s; }

add_secret() {
  [[ -n "${1:-}" ]] || return 0
  SECRETS_LIST="$SECRETS_LIST$1"$'\n'
}

# redact cuts every known secret and token, and anything shaped like a
# Tailscale key or a JWT, out of stdin.
redact() {
  SPEC_REDACT="$SECRETS_LIST" perl -pe '
    BEGIN { @s = grep { length } split /\n/, $ENV{SPEC_REDACT} }
    for my $x (@s) { s/\Q$x\E/[redacted]/g }
    s/tskey-[A-Za-z0-9_-]+/[redacted]/g;
    s/eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]*/[redacted]/g;
  '
}

# contains_secret FILE: whether FILE quotes any known secret.
contains_secret() {
  SPEC_REDACT="$SECRETS_LIST" perl -0777 -ne '
    BEGIN { @s = grep { length } split /\n/, $ENV{SPEC_REDACT} }
    for my $x (@s) { exit 0 if index($_, $x) >= 0 }
    exit 1;
  ' "$1"
}

# summary: the start of the last body, on one line, secrets cut.
summary() { { head -c 240 "$BODY" 2>/dev/null || true; } | tr '\n\t' '  ' | redact; }

# msg: the last body's message, secrets cut.
msg() {
  { jq -r '(.message // .error_description // .error // empty) | tostring' "$BODY" 2>/dev/null || true; } |
    head -c 200 | tr '\n' ' ' | redact
}

# err_body_ok: the last body is JSON with a string message or error.
err_body_ok() {
  jq -e '(.message | type) == "string" or (.error | type) == "string"' "$BODY" >/dev/null 2>&1
}

# ── HTTP ──────────────────────────────────────────────────────────────────

_q() {
  local s="$1"
  s="${s//\\/\\\\}"
  s="${s//\"/\\\"}"
  printf '%s' "$s"
}

# _track METHOD URL logs the last call (redacted) and feeds the run-wide
# checks: redirects (A22), 429s (A25), 5xx (A26), error bodies (A21) and
# timings (A28).
_track() {
  local method="$1" url="$2" path="${2#"$API"}"
  CALLS=$((CALLS + 1))
  if awk -v a="$SECS" -v b="$MAX_SECS" 'BEGIN { exit !(a > b) }'; then
    MAX_SECS="$SECS"
    MAX_SECS_WHAT="$method $path"
  fi
  case "$ST" in
    3??) N_3XX=$((N_3XX + 1)); LIST_3XX="$LIST_3XX $method $path ($ST);" ;;
  esac
  if [[ "$ST" == 429 ]]; then
    local ra
    ra="$(header retry-after)"
    N_429=$((N_429 + 1))
    RA_SEEN="$RA_SEEN ${ra:-none}"
    if [[ -n "$ra" && ! "$ra" =~ ^[0-9]+$ ]]; then RA_BAD="$RA_BAD $ra"; fi
  fi
  if [[ "$ST" == 5?? ]]; then
    N_5XX=$((N_5XX + 1))
    LIST_5XX="$LIST_5XX $method $path ($ST: $(summary));"
  fi
  if [[ "$ST" =~ ^[45] ]]; then
    N_ERR=$((N_ERR + 1))
    err_body_ok || BAD_ERR="$BAD_ERR $method $path ($ST: $(summary | head -c 80));"
  fi
  if [[ -s "$BODY" ]] && contains_secret "$BODY" && [[ ! "$path" =~ /oauth/ ]]; then
    SECRET_ECHO="$SECRET_ECHO $method $path;"
  fi
  {
    printf '%s %s %s -> %s in %ss\n' "$(date -u +%H:%M:%S)" "$method" "$path" "$ST" "$SECS"
    { head -c 2000 "$BODY" 2>/dev/null || true; } | redact
    printf '\n\n'
  } >>"$LOG" 2>/dev/null || true
}

# _http METHOD URL TOKEN DATA_FILE FORM [HEADER...] sends one request. The
# curl config, with the token and any form secret, goes to curl on stdin,
# never on a command line. Redirects aren't followed (A22). Sets ST and SECS,
# and leaves the body in $BODY and the headers in $HEADERS.
_http() {
  local method="$1" url="$2" token="$3" data="$4" form="$5"
  shift 5
  local h out names
  : >"$BODY"
  : >"$HEADERS"
  if dry; then
    names=""
    for h in "$@"; do names="$names, $h"; done
    [[ -n "$token" ]] && names="$names, Authorization: Bearer [token]"
    printf '  %sdry run%s %s %s%s' "$DIM" "$RESET" "$method" "${url#"$API"}" "${names:+ (${names#, })}"
    if [[ -n "$data" ]]; then printf ' body %s bytes' "$(wc -c <"$data" | tr -d ' ')"; fi
    if [[ -n "$form" ]]; then
      printf ' form %s' "$(printf '%s\n' "$form" | sed -E 's/^data-urlencode = "([^=]*)=.*/\1/' | tr '\n' ' ')"
    fi
    printf '\n'
    ST=000
    SECS=0
    CALLS=$((CALLS + 1))
    return 0
  fi
  out=$(
    {
      printf 'url = "%s"\n' "$(_q "$url")"
      printf 'request = "%s"\n' "$method"
      if [[ -n "$token" ]]; then
        printf 'header = "Authorization: Bearer %s"\n' "$(_q "$token")"
      fi
      for h in "$@"; do
        printf 'header = "%s"\n' "$(_q "$h")"
      done
      if [[ -n "$data" ]]; then
        printf 'data-binary = "@%s"\n' "$(_q "$data")"
      fi
      if [[ -n "$form" ]]; then
        printf '%s\n' "$form"
      fi
    } | curl -sS --max-time 30 -o "$BODY" -D "$HEADERS" -w '%{http_code} %{time_total}' --config - 2>"$WORK/curl.err"
  ) || out="000 0"
  ST="${out%% *}"
  SECS="${out#* }"
  # A token in the body is a secret from here on, before anything logs it.
  add_secret "$(jq -r '.access_token // empty' "$BODY" 2>/dev/null || true)"
  _track "$method" "$url"
}

# api METHOD PATH TOKEN [DATA_FILE] [HEADER...]: one call under /api/v2.
api() {
  local method="$1" path="$2" token="$3" data="${4:-}"
  if [[ $# -ge 4 ]]; then shift 4; else shift $#; fi
  _http "$method" "$API$path" "$token" "$data" "" "$@"
}

# header NAME: a response header's value from the last call.
header() {
  { grep -i "^$1:" "$HEADERS" 2>/dev/null || true; } | tail -n1 | cut -d' ' -f2- | tr -d '\r'
}

# quoted ETAG: If-Match wants it quoted, as Tailscale expects it.
quoted() {
  local e="${1#\"}"
  printf '"%s"' "${e%\"}"
}

st_in() { in_list "$ST" "$1"; }

# json_get FILTER: a jq filter on the last body, empty when it doesn't parse.
json_get() { jq -r "$1" "$BODY" 2>/dev/null || true; }

# jstr VALUE: VALUE as a JSON string.
jstr() { jq -n --arg s "$1" '$s'; }

# ── Tokens ────────────────────────────────────────────────────────────────

MINT_TOKEN=""
MINT_SCOPE=""
MINT_EXP=""
MINT_TYPE=""

_take_token() {
  MINT_TOKEN=""
  MINT_SCOPE=""
  MINT_EXP=""
  MINT_TYPE=""
  if dry; then MINT_TOKEN="dry-run-token"; return 0; fi
  [[ "$ST" == 200 ]] || return 0
  MINT_TOKEN="$(json_get '.access_token // empty')"
  MINT_SCOPE="$(json_get '.scope // empty')"
  MINT_EXP="$(json_get '.expires_in // empty')"
  MINT_TYPE="$(json_get '.token_type // empty')"
  add_secret "$MINT_TOKEN"
  jq '.access_token = "[token]"' "$BODY" >"$BODY.cut" 2>/dev/null && mv "$BODY.cut" "$BODY"
}

# mint_raw CLIENT_ID SECRET [SCOPE] [GRANT_TYPE]: POST /oauth/token. GRANT_TYPE
# "-" leaves grant_type out.
mint_raw() {
  local id="$1" secret="$2" scope="${3:-}" grant="${4:-client_credentials}" form=""
  add_secret "$secret"
  if [[ "$grant" != "-" ]]; then form="data-urlencode = \"grant_type=$(_q "$grant")\""$'\n'; fi
  form="${form}data-urlencode = \"client_id=$(_q "$id")\""$'\n'
  form="${form}data-urlencode = \"client_secret=$(_q "$secret")\""
  if [[ -n "$scope" ]]; then form="$form"$'\n'"data-urlencode = \"scope=$(_q "$scope")\""; fi
  _http POST "$API/oauth/token" "" "" "$form"
  _take_token
}

# exchange_raw CLIENT_ID JWT [SCOPE]: POST /oauth/token-exchange.
exchange_raw() {
  local id="$1" jwt="$2" scope="${3:-}" form
  add_secret "$jwt"
  form="data-urlencode = \"client_id=$(_q "$id")\""$'\n'"data-urlencode = \"jwt=$(_q "$jwt")\""
  if [[ -n "$scope" ]]; then form="$form"$'\n'"data-urlencode = \"scope=$(_q "$scope")\""; fi
  _http POST "$API/oauth/token-exchange" "" "" "$form"
  _take_token
}

# need_secret CLIENT: CLIENT is ADMIN, PO, RO, ALL or FREE. Asks for its secret,
# hidden, the first time. Fails when the client isn't set up.
need_secret() {
  local id_var="${1}_CLIENT_ID" secret_var="${1}_SECRET"
  [[ -n "${!id_var:-}" ]] || return 1
  if [[ -z "${!secret_var:-}" ]]; then
    # On macOS the secret may already be in the login Keychain, under service
    # p0-tailscale-spec and account <client in lower case>-secret, so a run
    # needs no pasting.
    local keychain_account; keychain_account="$(printf '%s' "$1" | tr '[:upper:]' '[:lower:]')-secret"
    if dry; then
      printf -v "$secret_var" '%s' "dry-run-secret"
    elif command -v security >/dev/null 2>&1 && security find-generic-password -s p0-tailscale-spec -a "$keychain_account" >/dev/null 2>&1; then
      printf -v "$secret_var" '%s' "$(security find-generic-password -s p0-tailscale-spec -a "$keychain_account" -w)"
      note "Read the $1 client's secret from the Keychain (p0-tailscale-spec/$keychain_account)."
    else
      ask_secret "$secret_var" "Secret of OAuth client ${!id_var} ($1), hidden:"
    fi
  fi
  add_secret "${!secret_var}"
  [[ -n "${!secret_var}" ]]
}

# token NAME sets TOKEN to a cached token: admin_full / po_full (no scope),
# admin_read / po_read (READ_SCOPES), po_write (the connector's WRITE_SCOPES,
# as it mints them) and admin_write (ADMIN_WRITE_SCOPES, the test's own lab
# policy writes). Re-mints after 50 minutes.
token() {
  local name="$1" var="TOK_$1" at_var="TOKAT_$1" client scope
  if [[ -n "${!var:-}" && $(($(now) - ${!at_var:-0})) -lt 3000 ]]; then
    TOKEN="${!var}"
    return 0
  fi
  case "$name" in
    admin_*) client=ADMIN ;;
    po_*) client=PO ;;
    *) return 1 ;;
  esac
  case "$name" in
    *_full) scope="" ;;
    *_read) scope="$READ_SCOPES" ;;
    admin_write) scope="$ADMIN_WRITE_SCOPES" ;;
    po_write) scope="$WRITE_SCOPES" ;;
  esac
  TOKEN=""
  if ! need_secret "$client"; then
    TOKEN_WHY="the $client OAuth client isn't set up"
    return 1
  fi
  local id_var="${client}_CLIENT_ID" secret_var="${client}_SECRET"
  mint_raw "${!id_var}" "${!secret_var}" "$scope"
  if [[ -n "$MINT_TOKEN" ]] && { dry || [[ "$ST" == 200 ]]; }; then
    printf -v "$var" '%s' "$MINT_TOKEN"
    printf -v "$at_var" '%s' "$(now)"
    TOKEN="$MINT_TOKEN"
    return 0
  fi
  TOKEN_WHY="minting $name answered $ST: $(msg)"
  return 1
}

forget_tokens() {
  local n
  for n in admin_full admin_read admin_write po_full po_read po_write; do
    printf -v "TOK_$n" '%s' ""
  done
}

# ── Results ───────────────────────────────────────────────────────────────

has_result() {
  local i
  for ((i = 0; i < ${#R_IDS[@]}; i++)); do
    [[ "${R_IDS[$i]}" == "$1" ]] && return 0
  done
  return 1
}

# res ID RESULT NOTE records one check's verdict, once.
res() {
  local id="$1" result="$2" note="${3:-}" color="$DIM"
  has_result "$id" && return 0
  if dry; then
    result=SKIP
    note="dry run"
  fi
  note="$(printf '%s' "$note" | tr '\n|' ' /' | redact)"
  R_IDS+=("$id")
  R_RES+=("$result")
  R_NOTES+=("$note")
  case "$result" in
    PASS) color="$GREEN" ;;
    FAIL) color="$RED" ;;
    HUMAN) color="$BLUE" ;;
  esac
  printf '  %s%s %s%s %s\n' "$color" "$id" "$result" "$RESET" "$note"
}

r_pass() { res "$CUR_ID" PASS "$*"; }
r_fail() { res "$CUR_ID" FAIL "$*"; }
r_skip() { res "$CUR_ID" SKIP "$*"; }
r_human() { res "$CUR_ID" HUMAN "$*"; }

# verdict OK NOTE: PASS when OK is 1, FAIL otherwise.
verdict() {
  if [[ "$1" == 1 ]]; then r_pass "$2"; else r_fail "$2"; fi
}

# hverdict OK NOTE: HUMAN when a person's answers matched the claim, FAIL otherwise.
hverdict() {
  if [[ "$1" == 1 ]]; then r_human "$2"; else r_fail "$2"; fi
}

# need VAR...: SKIP the current check when any setup value is missing.
need() {
  local v missing=""
  for v in "$@"; do
    [[ -n "${!v:-}" ]] || missing="$missing $v"
  done
  if [[ -n "$missing" ]]; then
    r_skip "setup missing:$missing (see admin-test.env.example)"
    return 1
  fi
}

# need_tok NAME: SKIP the current check when its token can't be minted.
need_tok() {
  if token "$1"; then return 0; fi
  r_skip "no $1 token: $TOKEN_WHY"
  return 1
}

defer() { DEFERRED="$DEFERRED $CUR_ID"; }

# ── People ────────────────────────────────────────────────────────────────

# human_do TEXT [PROMPT]: tells the person exactly what to do, then waits.
human_do() {
  step "$1"
  if dry; then return 0; fi
  if [[ "$UNATTENDED" == 1 ]]; then NEEDED_PERSON=1; return 0; fi
  pause "${2:-Press Enter when done.}"
}

# human_yn QUESTION: the person's y/n after doing something.
human_yn() {
  if dry; then
    note "(dry run, would ask) $1"
    return 1
  fi
  if [[ "$UNATTENDED" == 1 ]]; then NEEDED_PERSON=1; return 1; fi
  confirm "$1"
}

# human_event PROMPT: waits until something happens; the person types n if
# it never does.
human_event() {
  if dry; then
    note "(dry run, would wait) $1"
    return 0
  fi
  if [[ "$UNATTENDED" == 1 ]]; then NEEDED_PERSON=1; return 1; fi
  local reply=""
  printf '  %s%s%s %s[Enter when it happens, n if it never does]%s ' "$BOLD" "$1" "$RESET" "$DIM" "$RESET"
  read -r reply || true
  [[ ! "$reply" =~ ^[Nn] ]]
}

# gate QUESTION: a y/N before a burst. Yes in a dry run.
gate() {
  if dry || [[ "$UNATTENDED" == 1 ]]; then return 0; fi
  confirm "$1"
}

open_page() {
  if dry; then note "(dry run, would open) $1"; else open_url "$1"; fi
}

wait_secs() {
  if dry; then return 0; fi
  sleep "$1"
}

NC() { printf 'nc -vz -w 3 %s %s' "$1" "$2"; }

# baseline: before any connection check, nothing in the lab's own policy may
# let A reach B on PORT_B or SSH to it. Asked once, before a check writes
# anything, so its own posture or grant can't make A look like it already
# reaches B.
baseline() {
  if [[ -n "$BASELINE" ]]; then [[ "$BASELINE" == ok ]]; return; fi
  say "Connection checks need a clean baseline: nothing in the lab's policy lets A reach B on $PORT_B or SSH to it."
  human_do "On device A, run: $(NC "$DEVICE_B_HOST" "$PORT_B")"
  if human_yn "Did it connect?"; then
    BASELINE=bad
    warn "A already reaches B on $PORT_B, so connection checks are skipped. Remove that access from the lab policy and run them again."
    return 1
  fi
  human_do "On device A, run: tailscale ssh $SSH_USER@$DEVICE_B_HOST (Ctrl-C if it hangs)"
  if human_yn "Did it log in?"; then
    BASELINE=bad
    warn "A already has Tailscale SSH to B, so connection checks are skipped."
    return 1
  fi
  BASELINE=ok
}

need_baseline() {
  baseline && return 0
  r_skip "the lab policy already lets A reach B, so a connection proves nothing"
  return 1
}

# ── Time ──────────────────────────────────────────────────────────────────

# iso_in SECONDS [FRACTION]: UTC that many seconds from now (negative for the
# past), RFC 3339, with an optional fraction such as .123.
iso_in() {
  local e=$(($(now) + $1)) frac="${2:-}" t
  t="$(date -u -r "$e" +%Y-%m-%dT%H:%M:%S 2>/dev/null || date -u -d "@$e" +%Y-%m-%dT%H:%M:%S)"
  printf '%s%sZ' "$t" "$frac"
}

# iso_ms TIME: an RFC 3339 time as epoch milliseconds.
iso_ms() {
  perl -MTime::Local -e '
    $_ = shift;
    /^(\d+)-(\d+)-(\d+)T(\d+):(\d+):(\d+)(\.\d+)?(Z|[+-]\d\d:?\d\d)$/ or exit 1;
    $t = timegm($6, $5, $4, $3, $2 - 1, $1);
    $ms = int(($7 // 0) * 1000 + 0.5);
    $o = 0;
    if ($8 ne "Z") { ($sg, $h, $m) = $8 =~ /([+-])(\d\d):?(\d\d)/; $o = ($h * 3600 + $m * 60) * ($sg eq "+" ? 1 : -1) }
    print(($t - $o) * 1000 + $ms);
  ' "$1"
}

# ── Policy file ───────────────────────────────────────────────────────────

# policy_get TOKEN OUT: the policy file as HuJSON into OUT, its ETag into PETAG.
policy_get() {
  api GET "/tailnet/$TAILNET/acl" "$1" "" "Accept: application/hujson"
  cp "$BODY" "$2" 2>/dev/null || : >"$2"
  PETAG="$(header etag)"
  if dry; then cp "$ORIGINAL" "$2"; PETAG='"dry-run-etag"'; fi
}

# policy_post TOKEN FILE ETAG: writes FILE with a quoted If-Match, and keeps
# what Tailscale stored in $WORK/stored. Only the test writes the lab policy
# file, to set up postures. The connector never does.
policy_post() {
  local etag
  etag="$(quoted "$3")"
  api POST "/tailnet/$TAILNET/acl" "$1" "$2" \
    "Content-Type: application/hujson" "Accept: application/hujson" "If-Match: $etag"
  cp "$BODY" "$WORK/stored" 2>/dev/null || : >"$WORK/stored"
  if [[ "$ST" == 200 ]]; then
    PETAG="$(header etag)"
    LAST_WRITE_ETAG="$PETAG"
    cp "$2" "$WORK/last-sent"
    POLICY_DIRTY=1
  fi
}

# is_own_write: the file just read is still this run's last write. Tailscale
# reformats a policy file when it stores it, so the bytes read back never
# match the bytes sent; the ETag of the write does.
is_own_write() {
  [[ -n "$LAST_WRITE_ETAG" && "$PETAG" == "$LAST_WRITE_ETAG" ]] ||
    cmp -s "$WORK/current.hujson" "$WORK/last-sent" ||
    cmp -s "$WORK/current.hujson" "$WORK/stored"
}

# snapshot: saves the original policy file and its ETag, once per run.
snapshot() {
  [[ "$SNAPSHOT_DONE" == 1 ]] && return 0
  if dry; then
    printf '{\n  // dry run: a placeholder for the lab policy file\n  "grants": [],\n}\n' >"$ORIGINAL"
    ORIG_ETAG='"dry-run-etag"'
    SNAPSHOT_DONE=1
    return 0
  fi
  token admin_write || { TOKEN_WHY="no admin_write token to snapshot the policy file: $TOKEN_WHY"; return 1; }
  api GET "/tailnet/$TAILNET/acl" "$TOKEN" "" "Accept: application/hujson"
  if [[ "$ST" != 200 || -z "$(header etag)" ]]; then
    TOKEN_WHY="couldn't snapshot the policy file (HTTP $ST, ETag '$(header etag)')"
    return 1
  fi
  cp "$BODY" "$ORIGINAL"
  chmod 600 "$ORIGINAL"
  ORIG_ETAG="$(header etag)"
  SNAPSHOT_DONE=1
  note "Saved the original policy file (ETag $ORIG_ETAG) to $ORIGINAL"
}

need_snapshot() {
  if [[ "$POLICY_BROKEN" == 1 ]]; then
    r_skip "an earlier restore of the policy file failed, so no more policy checks run; restore it from $ORIGINAL"
    return 1
  fi
  snapshot && return 0
  r_skip "$TOKEN_WHY"
  return 1
}

# restore_policy writes the original back with If-Match, unless someone
# else changed the file since this run wrote it.
restore_policy() {
  [[ "$POLICY_DIRTY" == 1 ]] || return 0
  dry && { POLICY_DIRTY=0; return 0; }
  token admin_write || { warn "no token to restore the policy file: $TOKEN_WHY. The original is at $ORIGINAL"; return 1; }
  policy_get "$TOKEN" "$WORK/current.hujson"
  if [[ "$ST" != 200 ]]; then
    warn "couldn't read the policy file to restore it (HTTP $ST). The original is at $ORIGINAL"
    return 1
  fi
  if cmp -s "$WORK/current.hujson" "$ORIGINAL"; then
    POLICY_DIRTY=0
    return 0
  fi
  if ! is_own_write; then
    warn "the policy file changed since this run wrote it, so it isn't overwritten. The original is at $ORIGINAL"
    return 1
  fi
  policy_post "$TOKEN" "$ORIGINAL" "$PETAG"
  if [[ "$ST" == 200 ]]; then
    POLICY_DIRTY=0
    return 0
  fi
  warn "restoring the policy file failed (HTTP $ST: $(summary)). The original is at $ORIGINAL"
  return 1
}

# post_current FILE: reads the current ETag and writes FILE with it, but
# only over the original or this run's own last write. Anything else means
# someone changed the file during the run, and nothing more is written.
post_current() {
  policy_get "$TOKEN" "$WORK/current.hujson"
  if ! dry && ! cmp -s "$WORK/current.hujson" "$ORIGINAL" && ! is_own_write; then
    warn "the policy file changed outside this run, so this run stops writing it. The original is at $ORIGINAL"
    POLICY_BROKEN=1
    ST=000
    return 1
  fi
  policy_post "$TOKEN" "$1" "$PETAG"
}

# sec_insert FILE SECTION OPEN TEXT OUT puts TEXT right after SECTION's
# opening bracket (matched without regard to case, as the connector does),
# or adds SECTION at the root holding TEXT. Text insertions only, so every
# other byte stays.
sec_insert() {
  local file="$1" section="$2" open="$3" text="$4" out="$5" close="]"
  [[ "$open" == "{" ]] && close="}"
  if SEC="$section" OPEN="$open" perl -0777 -ne '
      BEGIN { $s = quotemeta $ENV{SEC}; $o = quotemeta $ENV{OPEN} }
      exit(/"$s"\s*:\s*$o/i ? 0 : 1)' "$file"; then
    SEC="$section" OPEN="$open" TXT="$text" perl -0777 -pe '
      BEGIN { $s = quotemeta $ENV{SEC}; $o = quotemeta $ENV{OPEN}; $t = $ENV{TXT} }
      s/("$s"\s*:\s*$o)/$1$t/i' "$file" >"$out"
  else
    root_insert "$file" $'\n  '"\"$section\": $open$text"$'\n  '"$close," "$out"
  fi
}

# root_insert FILE TEXT OUT puts TEXT right after the root object's "{".
root_insert() {
  TXT="$2" perl -0777 -pe '
    BEGIN { $t = $ENV{TXT} }
    s/\A((?:\s+|\/\/[^\n]*\n|\/\*.*?\*\/)*\{)/$1$t/s' "$1" >"$3"
}

# has_key FILE KEY [exact]: whether "KEY": appears, without regard to case
# unless "exact".
has_key() {
  KEYN="$2" EXACT="${3:-}" perl -0777 -ne '
    BEGIN { $k = quotemeta $ENV{KEYN} }
    if ($ENV{EXACT}) { exit(/"$k"\s*:/ ? 0 : 1) } else { exit(/"$k"\s*:/i ? 0 : 1) }' "$1"
}

# The policy builder: pol_new copies the original into $P, and each pol_*
# adds one entry to it.
pol_new() { cp "$ORIGINAL" "$P"; }
pol_raw() { sec_insert "$P" "$1" "$2" "$3" "$P.next" && mv "$P.next" "$P"; }
pol_add() { pol_raw "$1" "$2" $'\n    '"$3,"; }
pol_grant() { pol_add grants "[" "$1"; }
pol_ssh() { pol_add ssh "[" "$1"; }
pol_posture() { pol_add postures "{" "\"$1\": $2"; }
pol_root() { root_insert "$P" $'\n  '"\"$1\": $2," "$P.next" && mv "$P.next" "$P"; }

# validate FILE runs FILE through /acl/validate with the read token, to see
# whether Tailscale takes a posture or grant shape the customer would write.
# Sets V_OK (yes or no), V_ERR and V_WARN (counts), and V_WHY (the first
# error, or the message).
validate() {
  V_OK=no
  V_ERR=0
  V_WARN=0
  V_WHY=""
  if ! token admin_read; then
    V_WHY="no admin_read token: $TOKEN_WHY"
    return 0
  fi
  api POST "/tailnet/$TAILNET/acl/validate" "$TOKEN" "$1" "Content-Type: application/hujson"
  if [[ "$ST" != 200 ]]; then
    V_WHY="HTTP $ST: $(msg)"
    dry && V_OK=yes
    return 0
  fi
  local message
  V_ERR="$(json_get '[.data[]?.errors[]?] | length')"
  V_WARN="$(json_get '[.data[]?.warnings[]?] | length')"
  message="$(json_get '.message // empty')"
  [[ -n "$V_ERR" ]] || V_ERR=0
  [[ -n "$V_WARN" ]] || V_WARN=0
  if [[ "$V_ERR" == 0 && -n "$message" ]] && ! printf '%s' "$message" | grep -qi warning; then
    V_ERR=1
  fi
  V_WHY="$(json_get '[.data[]?.errors[]?][0] // .message // empty' | head -c 160 | redact)"
  [[ "$V_ERR" == 0 ]] && V_OK=yes
}

# ── Device attributes ─────────────────────────────────────────────────────

uri() { jq -rn --arg s "$1" '$s | @uri'; }

attr_track() { ATTRS+=("$1|$2"); }

# attr_post DEVICE KEY VALUE_JSON EXPIRY [COMMENT]: POST one attribute.
attr_post() {
  attr_track "$1" "$2"
  jq -n --argjson v "$3" --arg e "$4" --arg c "${5:-$COMMENT}" \
    '{value: $v, expiry: $e, comment: $c}' >"$WORK/attr.json"
  api POST "/device/$1/attributes/$(uri "$2")" "$TOKEN" "$WORK/attr.json" "Content-Type: application/json"
}

# attr_patch NODES_JSON [COMMENT]: one PATCH /device-attributes.
attr_patch() {
  jq -n --argjson n "$1" --arg c "${2:-$COMMENT}" '{nodes: $n, comment: $c}' >"$WORK/patch.json"
  api PATCH "/tailnet/$TAILNET/device-attributes" "$TOKEN" "$WORK/patch.json" "Content-Type: application/json"
}

# attr_set_one DEVICE KEY SECONDS: sets KEY true on DEVICE for SECONDS, by PATCH.
attr_set_one() {
  attr_track "$1" "$2"
  attr_patch "$(jq -n --arg d "$1" --arg k "$2" --arg e "$(iso_in "$3" .000)" '{($d): {($k): {value: true, expiry: $e}}}')"
}

attr_unset_one() {
  attr_patch "$(jq -n --arg d "$1" --arg k "$2" '{($d): {($k): null}}')"
}

# attr_read DEVICE: GET its attributes into $BODY.
attr_read() { api GET "/device/$1/attributes" "$TOKEN" ""; }

# attr_val KEY: KEY's value in the last attribute read, or "absent".
attr_value() { jq -r --arg k "$1" '.attributes[$k] // "absent" | tostring' "$BODY" 2>/dev/null || true; }
attr_type() { jq -r --arg k "$1" '.attributes[$k] | type' "$BODY" 2>/dev/null || true; }
attr_expiry() { jq -r --arg k "$1" '.expiries[$k] // empty' "$BODY" 2>/dev/null || true; }

# clear_attrs deletes every attribute this run may have set.
clear_attrs() {
  [[ ${#ATTRS[@]} -gt 0 ]] || return 0
  dry && { ATTRS=(); return 0; }
  token po_write || { warn "no token to remove the test attributes: $TOKEN_WHY"; return 1; }
  local i pair done_list=" "
  for ((i = 0; i < ${#ATTRS[@]}; i++)); do
    pair="${ATTRS[$i]}"
    in_list "$pair" "$done_list" && continue
    done_list="$done_list$pair "
    api DELETE "/device/${pair%%|*}/attributes/$(uri "${pair#*|}")" "$TOKEN" ""
    if [[ "$ST" != 200 && "$ST" != 404 ]]; then
      warn "couldn't remove ${pair#*|} from ${pair%%|*} (HTTP $ST)"
    fi
  done
  ATTRS=()
}

# settle undoes whatever the last check left: the policy file and the test
# attributes.
settle() {
  restore_policy || POLICY_BROKEN=1
  clear_attrs || true
}

# ── Federated identity tokens ─────────────────────────────────────────────
#
# Run logins for me: these sign in where needed and mint the subject token
# themselves. Every token stays in a shell variable.

run_aws() {
  if [[ -n "$SPEC_AWS_PROFILE" ]]; then AWS_PROFILE="$SPEC_AWS_PROFILE" aws "$@"; else aws "$@"; fi
}

aws_login() {
  if dry; then
    note "(dry run, would run) aws sts get-caller-identity${SPEC_AWS_PROFILE:+ --profile $SPEC_AWS_PROFILE}, and aws sso login if that fails"
    return 0
  fi
  command -v aws >/dev/null 2>&1 || { SUBJ_WHY="the aws CLI isn't installed"; return 1; }
  if ! run_aws sts get-caller-identity >/dev/null 2>&1; then
    say "Signing in to AWS${SPEC_AWS_PROFILE:+ (profile $SPEC_AWS_PROFILE)}."
    run_aws sso login || { SUBJ_WHY="aws sso login failed"; return 1; }
  fi
}

# aws_subject AUDIENCE: assumes FED_AWS_ROLE_ARN, as the Lambda runs, and
# mints an ES384 outbound identity token of 300 s for AUDIENCE into SUBJ.
aws_subject() {
  SUBJ=""
  aws_login || return 1
  if dry; then
    note "(dry run, would run) aws sts assume-role --role-arn $FED_AWS_ROLE_ARN, then aws sts get-web-identity-token --audience $1 --signing-algorithm ES384 --duration-seconds 300"
    SUBJ="eyJhbGciOiJFUzM4NCJ9.eyJzdWIiOiJkcnkifQ.c2ln"
    return 0
  fi
  local creds ak sk st region=""
  creds="$(run_aws sts assume-role --role-arn "$FED_AWS_ROLE_ARN" --role-session-name "p0-spec-$RID" \
    --duration-seconds 900 --query 'Credentials.[AccessKeyId,SecretAccessKey,SessionToken]' --output text 2>"$WORK/aws.err")" ||
    { SUBJ_WHY="aws sts assume-role failed: $(head -c 200 "$WORK/aws.err" | redact)"; return 1; }
  read -r ak sk st <<<"$creds"
  add_secret "$sk"
  add_secret "$st"
  [[ -n "$SPEC_AWS_REGION" ]] && region="$SPEC_AWS_REGION"
  SUBJ="$(
    unset AWS_PROFILE
    export AWS_ACCESS_KEY_ID="$ak" AWS_SECRET_ACCESS_KEY="$sk" AWS_SESSION_TOKEN="$st"
    if [[ -n "$region" ]]; then export AWS_REGION="$region"; fi
    aws sts get-web-identity-token --audience "$1" --signing-algorithm ES384 --duration-seconds 300 \
      --query WebIdentityToken --output text 2>"$WORK/aws.err"
  )" || { SUBJ=""; SUBJ_WHY="aws sts get-web-identity-token failed: $(head -c 200 "$WORK/aws.err" | redact)"; return 1; }
  add_secret "$SUBJ"
  [[ -n "$SUBJ" ]]
}

gcp_login() {
  if dry; then
    note "(dry run, would run) gcloud auth list, and gcloud auth login if no account is active"
    return 0
  fi
  command -v gcloud >/dev/null 2>&1 || { SUBJ_WHY="the gcloud CLI isn't installed"; return 1; }
  if [[ -z "$(gcloud auth list --filter=status:ACTIVE --format='value(account)' 2>/dev/null)" ]]; then
    say "Signing in to Google Cloud."
    gcloud auth login || { SUBJ_WHY="gcloud auth login failed"; return 1; }
  fi
}

# gcp_subject AUDIENCE: an ID token for FED_GCP_SA and AUDIENCE into SUBJ.
gcp_subject() {
  SUBJ=""
  gcp_login || return 1
  if dry; then
    note "(dry run, would run) gcloud auth print-identity-token --impersonate-service-account=$FED_GCP_SA --audiences=$1 --include-email"
    SUBJ="eyJhbGciOiJSUzI1NiJ9.eyJzdWIiOiJkcnkifQ.c2ln"
    return 0
  fi
  SUBJ="$(gcloud auth print-identity-token --impersonate-service-account="$FED_GCP_SA" \
    --audiences="$1" --include-email ${GCP_PROJECT:+--project="$GCP_PROJECT"} 2>"$WORK/gcp.err")" ||
    { SUBJ=""; SUBJ_WHY="gcloud auth print-identity-token failed: $(head -c 200 "$WORK/gcp.err" | redact)"; return 1; }
  add_secret "$SUBJ"
  [[ -n "$SUBJ" ]]
}

# jwt_json PART: decodes part 0 (header) or 1 (claims) of SUBJ.
jwt_json() {
  printf '%s' "$SUBJ" | cut -d. -f"$(($1 + 1))" | perl -MMIME::Base64 -ne '
    chomp; tr{-_}{+/}; $_ .= "=" x ((4 - length() % 4) % 4); print decode_base64($_)'
}

# fed_sources: the federated identities set up, "aws" and or "gcp".
fed_sources() {
  local out=""
  [[ -n "$FED_AWS_CLIENT_ID" && -n "$FED_AWS_ROLE_ARN" ]] && out="$out aws"
  [[ -n "$FED_GCP_CLIENT_ID" && -n "$FED_GCP_SA" ]] && out="$out gcp"
  printf '%s' "${out# }"
}

fed_client() { if [[ "$1" == aws ]]; then printf '%s' "$FED_AWS_CLIENT_ID"; else printf '%s' "$FED_GCP_CLIENT_ID"; fi; }
fed_scopes() { if [[ "$1" == aws ]]; then printf '%s' "$FED_AWS_SCOPES"; else printf '%s' "$FED_GCP_SCOPES"; fi; }

# fed_subject SOURCE AUDIENCE mints SOURCE's subject token into SUBJ.
fed_subject() {
  SUBJ_WHY=""
  if [[ "$1" == aws ]]; then aws_subject "$2"; else gcp_subject "$2"; fi
}

need_fed() {
  [[ -n "$(fed_sources)" ]] && return 0
  r_skip "setup missing: FED_AWS_CLIENT_ID and FED_AWS_ROLE_ARN, or FED_GCP_CLIENT_ID and FED_GCP_SA"
  return 1
}

# sorted_words TEXT: TEXT's words, sorted and unique, on one line.
sorted_words() { printf '%s\n' $1 | sort -u | tr '\n' ' ' | sed 's/ $//'; }

# ── Lab facts the checks share ────────────────────────────────────────────

# lab_dns: the tailnet's DNS name, from TAILNET_DNS or the first own
# device's MagicDNS name, as the connector derives it.
lab_dns() {
  if [[ -n "$TAILNET_DNS" ]]; then printf '%s' "$TAILNET_DNS"; return 0; fi
  token admin_read || return 1
  api GET "/tailnet/$TAILNET/devices" "$TOKEN" ""
  TAILNET_DNS="$(json_get '[.devices[]? | select(.isExternal != true) | .name][0] // empty' | sed -E 's/^[^.]*\.//; s/\.$//')"
  [[ -n "$TAILNET_DNS" ]] && printf '%s' "$TAILNET_DNS"
}

# Quoted names for policy entries.
QL='""'
QTAG='""'
QUSER='""'
quote_inputs() {
  QL="$(jstr "$LOGIN")"
  QTAG="$(jstr "$TAG_B")"
  QUSER="$(jstr "$SSH_USER")"
}

grant_to_b() { printf '{"src": [%s], "dst": [%s], "ip": ["tcp:%s"]%s}' "$1" "$QTAG" "${2:-$PORT_B}" "${3:-}"; }
ssh_rule() { printf '{"action": "accept", "src": [%s], "dst": [%s], "users": ["autogroup:nonroot", %s]%s}' "$1" "$QTAG" "$QUSER" "${2:-}"; }

# ══════════════════════════════════════════════════════════════════════════
# Checks. Each t_<ID> records one verdict for its ID.
# ══════════════════════════════════════════════════════════════════════════

# ── 1. OAuth client credentials ───────────────────────────────────────────

t_A01() {
  need ADMIN_CLIENT_ID || return 0
  need_secret ADMIN || { r_skip "no admin secret"; return 0; }
  mint_raw "$ADMIN_CLIENT_ID" "$ADMIN_SECRET"
  local ok=1 re='^[A-Za-z0-9_.+/=-]+$'
  [[ "$ST" == 200 ]] || ok=0
  printf '%s' "$MINT_TYPE" | grep -qi '^bearer$' || ok=0
  [[ "$MINT_EXP" == 3600 ]] || ok=0
  [[ "$MINT_TOKEN" == tskey-* && "$MINT_TOKEN" =~ $re ]] || ok=0
  verdict "$ok" "HTTP $ST, token_type ${MINT_TYPE:-none}, expires_in ${MINT_EXP:-none}, token starts tskey-: $([[ "$MINT_TOKEN" == tskey-* ]] && echo yes || echo no), scope: ${MINT_SCOPE:-none}"
}

t_A02() {
  need ADMIN_CLIENT_ID || return 0
  need_secret ADMIN || { r_skip "no admin secret"; return 0; }
  local ok=1 n="" want got
  mint_raw "$ADMIN_CLIENT_ID" "$ADMIN_SECRET"
  want="$(sorted_words "$ADMIN_SCOPES")"
  got="$(sorted_words "$MINT_SCOPE")"
  [[ "$ST" == 200 && "$got" == "$want" ]] || ok=0
  n="admin: HTTP $ST, scope '$MINT_SCOPE'"
  if need_secret PO 2>/dev/null; then
    mint_raw "$PO_CLIENT_ID" "$PO_SECRET"
    want="$(sorted_words "$PO_SCOPES")"
    got="$(sorted_words "$MINT_SCOPE")"
    [[ "$ST" == 200 && "$got" == "$want" ]] || ok=0
    n="$n; connector: HTTP $ST, scope '$MINT_SCOPE'"
  else
    n="$n; the connector's client isn't set up"
  fi
  verdict "$ok" "$n (expected each client's configured set, ADMIN_SCOPES and PO_SCOPES)"
}

t_A03() {
  need ADMIN_CLIENT_ID DEVICE_A DEVICE_B || return 0
  need_secret ADMIN || { r_skip "no admin secret"; return 0; }
  local ok=1 n="" client tok missing ep
  for client in ADMIN PO; do
    if [[ "$client" == PO ]] && ! need_secret PO; then n="$n; the connector's client isn't set up"; continue; fi
    local id_var="${client}_CLIENT_ID" secret_var="${client}_SECRET"
    mint_raw "${!id_var}" "${!secret_var}" "$READ_SCOPES"
    tok="$MINT_TOKEN"
    missing=""
    for ep in $READ_SCOPES; do in_list "$ep" "$MINT_SCOPE" || missing="$missing $ep"; done
    if [[ "$ST" != 200 ]]; then
      ok=0
      n="$n; $client READ_SCOPES mint HTTP $ST: $(msg)"
      continue
    fi
    [[ -z "$missing" ]] || ok=0
    n="$n; $client mint 200${missing:+, scope lacks$missing}"
    for ep in "/tailnet/$TAILNET/acl" "/device/$DEVICE_A/attributes" "/tailnet/$TAILNET/users" \
      "/tailnet/$TAILNET/devices" "/device/$DEVICE_B/routes" "/tailnet/$TAILNET/services"; do
      api GET "$ep" "$tok" ""
      if [[ "$ST" != 200 ]]; then
        ok=0
        n="$n, GET ${ep#/tailnet/"$TAILNET"} $ST"
      fi
    done
  done
  verdict "$ok" "${n#; }"
}

t_A04() {
  need PO_CLIENT_ID || return 0
  need_secret PO || { r_skip "no PO secret"; return 0; }
  local ok=1 n="" scope
  for scope in "policy_file" "users:read policy_file"; do
    mint_raw "$PO_CLIENT_ID" "$PO_SECRET" "$scope"
    { [[ "$ST" == 400 ]] && err_body_ok; } || ok=0
    n="$n; '$scope': HTTP $ST $(msg)"
  done
  verdict "$ok" "${n#; } (expected 400 with an OAuth error body)"
}

t_A06() {
  need ADMIN_CLIENT_ID || return 0
  need_secret ADMIN || { r_skip "no admin secret"; return 0; }
  local ok=1 n="" wrong="tskey-client-kSpecWrong$RID-notasecret$RID"
  mint_raw "$ADMIN_CLIENT_ID" "$wrong"
  { st_in "400 401" && err_body_ok; } || ok=0
  n="wrong secret: $ST $(msg)"
  mint_raw "kNoSuchClient$RID" "$wrong"
  { st_in "400 401" && err_body_ok; } || ok=0
  n="$n; unknown client: $ST $(msg)"
  mint_raw "$ADMIN_CLIENT_ID" "$ADMIN_SECRET" "" "-"
  { st_in "400 401" && err_body_ok; } || ok=0
  if [[ -s "$BODY" ]] && contains_secret "$BODY"; then
    ok=0
    n="$n; a body quoted the secret"
  fi
  n="$n; no grant_type: $ST $(msg)"
  verdict "$ok" "$n"
}

A07_TOKEN=""
A07_AT=0
t_A07() {
  need ADMIN_CLIENT_ID || return 0
  need_secret ADMIN || { r_skip "no admin secret"; return 0; }
  mint_raw "$ADMIN_CLIENT_ID" "$ADMIN_SECRET" "users:read"
  if [[ "$ST" != 200 ]] && ! dry; then
    r_fail "couldn't mint a token to hold: HTTP $ST $(msg)"
    return 0
  fi
  A07_TOKEN="$MINT_TOKEN"
  A07_AT="$(now)"
  note "Minted a token; it's tried again at the end, $TOKEN_WAIT_MINUTES minutes after now."
  defer
}

finish_A07() {
  local left=$((TOKEN_WAIT_MINUTES * 60 - ($(now) - A07_AT)))
  if [[ "$left" -gt 0 ]] && ! dry; then
    if ! confirm "A07: wait $(((left + 59) / 60)) more minutes to try the token again?"; then
      r_skip "not waited: $((($(now) - A07_AT) / 60)) of $TOKEN_WAIT_MINUTES minutes passed"
      return 0
    fi
    while [[ "$left" -gt 0 ]]; do
      printf '\r  %s%s minutes left%s ' "$DIM" "$(((left + 59) / 60))" "$RESET"
      sleep 60
      left=$((TOKEN_WAIT_MINUTES * 60 - ($(now) - A07_AT)))
    done
    printf '\n'
  fi
  api GET "/tailnet/$TAILNET/users" "$A07_TOKEN" ""
  verdict "$([[ "$ST" == 200 ]] && echo 1 || echo 0)" "after $((($(now) - A07_AT) / 60)) minutes: HTTP $ST"
}

t_A08() {
  if dry; then Z_CLIENT_ID="kDryRunZ"; Z_SECRET="dry-run-secret"; fi
  local ok=1 n="" ztok
  open_page "$CONSOLE/settings/trust-credentials"
  human_do "Settings > Trust credentials (OAuth clients): create a throwaway OAuth client with only users:read. Name it p0-spec-$RID."
  if ! dry; then
    ask Z_CLIENT_ID "Its client ID:"
    ask_secret Z_SECRET "Its client secret, hidden:"
  fi
  [[ -n "${Z_CLIENT_ID:-}" && -n "${Z_SECRET:-}" ]] || { r_skip "no throwaway client given"; return 0; }
  mint_raw "$Z_CLIENT_ID" "$Z_SECRET"
  ztok="$MINT_TOKEN"
  if [[ "$ST" != 200 ]] && ! dry; then
    r_fail "the throwaway client's mint answered $ST $(msg)"
    return 0
  fi
  api GET "/tailnet/$TAILNET/users" "$ztok" ""
  n="before: users $ST"
  human_do "Now delete the OAuth client p0-spec-$RID in the console."
  api GET "/tailnet/$TAILNET/users" "$ztok" ""
  [[ "$ST" == 401 ]] || ok=0
  n="$n; old token after the delete: $ST $(msg)"
  mint_raw "$Z_CLIENT_ID" "$Z_SECRET"
  st_in "400 401" || ok=0
  n="$n; fresh mint: $ST $(msg)"
  Z_SECRET=""
  hverdict "$ok" "$n (expected 401, then 400 or 401)"
}

t_A09() {
  need ADMIN_CLIENT_ID || return 0
  need_secret ADMIN || { r_skip "no admin secret"; return 0; }
  open_page "$CONSOLE/settings/trust-credentials"
  human_do "Open the admin OAuth client $ADMIN_CLIENT_ID and look for a way to issue it a new secret (regenerate or rotate). Don't create a new client."
  if ! human_yn "Is there a way to issue a new secret for the same client?"; then
    r_human "new client required: the console has no in-place rotation, so rotating means a new client ID and removing and re-adding the tailnet"
    return 0
  fi
  human_do "Issue the new secret and copy it."
  local old="$ADMIN_SECRET" new="" ok=1 n=""
  if ! dry; then ask_secret NEW_ADMIN_SECRET "The new secret, hidden:"; new="${NEW_ADMIN_SECRET:-}"; NEW_ADMIN_SECRET=""; fi
  add_secret "$new"
  mint_raw "$ADMIN_CLIENT_ID" "$old"
  st_in "400 401" || ok=0
  n="old secret: $ST"
  mint_raw "$ADMIN_CLIENT_ID" "$new"
  [[ "$ST" == 200 ]] || ok=0
  n="$n; new secret: $ST, same client ID $ADMIN_CLIENT_ID"
  if [[ "$ST" == 200 ]]; then
    ADMIN_SECRET="$new"
    forget_tokens
    n="$n; the rest of this run uses the new secret"
  fi
  hverdict "$ok" "in-place rotation: $n"
}

t_A10() {
  need RO_CLIENT_ID DEVICE_A || return 0
  need_secret RO || { r_skip "no RO secret"; return 0; }
  local ok=1 n="" tok ep
  mint_raw "$RO_CLIENT_ID" "$RO_SECRET"
  tok="$MINT_TOKEN"
  [[ "$ST" == 200 ]] || ok=0
  n="RO mint $ST, scope '$MINT_SCOPE'"
  for ep in "/tailnet/$TAILNET/users" "/tailnet/$TAILNET/devices" "/device/$DEVICE_A/routes" \
    "/device/$DEVICE_A/attributes" "/tailnet/$TAILNET/services" "/tailnet/$TAILNET/acl"; do
    api GET "$ep" "$tok" ""
    if [[ "$ST" != 200 ]]; then ok=0; n="$n, GET ${ep#/tailnet/"$TAILNET"} $ST"; fi
  done
  mint_raw "$RO_CLIENT_ID" "$RO_SECRET" "policy_file"
  [[ "$ST" == 400 ]] || ok=0
  n="$n; RO asking policy_file: $ST"
  if [[ -n "$ALL_CLIENT_ID" ]] && need_secret ALL; then
    mint_raw "$ALL_CLIENT_ID" "$ALL_SECRET"
    tok="$MINT_TOKEN"
    [[ "$ST" == 200 ]] || ok=0
    n="$n; ALL mint $ST, scope '$MINT_SCOPE'"
    api GET "/tailnet/$TAILNET/acl" "$tok" ""
    [[ "$ST" == 200 ]] || ok=0
    n="$n, GET /acl $ST"
  else
    n="$n; ALL not set up"
  fi
  verdict "$ok" "$n"
}

# ── 2. Federated token exchange ───────────────────────────────────────────

t_A11() {
  need_fed || return 0
  local ok=1 n="" src aud
  for src in $(fed_sources); do
    aud="api.tailscale.com/$(fed_client "$src")"
    if ! fed_subject "$src" "$aud"; then ok=0; n="$n; $src: $SUBJ_WHY"; continue; fi
    exchange_raw "$(fed_client "$src")" "$SUBJ"
    { [[ "$ST" == 200 && -n "$MINT_TOKEN" && -n "$MINT_EXP" ]] || dry; } || ok=0
    n="$n; $src: HTTP $ST, expires_in ${MINT_EXP:-none}"
    exchange_raw "$(fed_client "$src")" "$SUBJ" "users:read"
    n="$n, with scope=users:read: HTTP $ST scope '${MINT_SCOPE:-none}' $(msg) (recorded)"
  done
  hverdict "$ok" "${n#; }"
}

t_A12() {
  need_fed || return 0
  local ok=1 n="" src want got
  for src in $(fed_sources); do
    if ! fed_subject "$src" "api.tailscale.com/$(fed_client "$src")"; then ok=0; n="$n; $src: $SUBJ_WHY"; continue; fi
    exchange_raw "$(fed_client "$src")" "$SUBJ"
    want="$(sorted_words "$(fed_scopes "$src")")"
    got="$(sorted_words "$MINT_SCOPE")"
    [[ "$ST" == 200 && -n "$MINT_SCOPE" && "$got" == "$want" ]] || ok=0
    n="$n; $src: HTTP $ST, scope '${MINT_SCOPE:-absent}'"
  done
  hverdict "$ok" "${n#; } (expected FED_*_SCOPES)"
}

t_A13() {
  need_fed || return 0
  local ok=1 n="" src id
  for src in $(fed_sources); do
    id="$(fed_client "$src")"
    open_page "$CONSOLE/settings/trust-credentials"
    human_do "Open the $src federated identity $id and read its audience."
    if ! human_yn "Is it exactly api.tailscale.com/$id?"; then
      dry || { ok=0; n="$n; $src: the console shows another audience"; }
    fi
    if fed_subject "$src" "api.tailscale.com/$id"; then
      exchange_raw "$id" "$SUBJ"
      [[ "$ST" == 200 ]] || ok=0
      n="$n; $src right audience: $ST"
    else
      ok=0
      n="$n; $src: $SUBJ_WHY"
    fi
    if fed_subject "$src" "api.tailscale.com/wrong$RID"; then
      exchange_raw "$id" "$SUBJ"
      st_in "400 401 403" || ok=0
      n="$n, wrong audience: $ST $(msg)"
    else
      n="$n, wrong audience: couldn't mint ($SUBJ_WHY)"
    fi
  done
  hverdict "$ok" "${n#; }"
}

t_A14() {
  need FED_AWS_CLIENT_ID FED_AWS_ROLE_ARN || return 0
  local ok=1 sub iss alg n
  if ! aws_subject "api.tailscale.com/$FED_AWS_CLIENT_ID"; then
    r_fail "couldn't mint the AWS token: $SUBJ_WHY"
    return 0
  fi
  sub="$(jwt_json 1 | jq -r '.sub // empty' 2>/dev/null || true)"
  iss="$(jwt_json 1 | jq -r '.iss // empty' 2>/dev/null || true)"
  alg="$(jwt_json 0 | jq -r '.alg // empty' 2>/dev/null || true)"
  [[ "$sub" == "$FED_AWS_ROLE_ARN" ]] || ok=0
  [[ "$alg" == ES384 ]] || ok=0
  exchange_raw "$FED_AWS_CLIENT_ID" "$SUBJ"
  [[ "$ST" == 200 ]] || ok=0
  n="sub '$sub' (role ARN $FED_AWS_ROLE_ARN), alg $alg, iss $iss, exchange $ST $(msg)"
  [[ "$sub" == arn:aws:sts::*:assumed-role/* ]] && n="$n; sub is the session ARN, not the role ARN"
  hverdict "$ok" "$n"
}

t_A15() {
  need FED_GCP_CLIENT_ID FED_GCP_SA || return 0
  local ok=1 sub iss uid="" n
  if ! gcp_subject "api.tailscale.com/$FED_GCP_CLIENT_ID"; then
    r_fail "couldn't mint the Google token: $SUBJ_WHY"
    return 0
  fi
  sub="$(jwt_json 1 | jq -r '.sub // empty' 2>/dev/null || true)"
  iss="$(jwt_json 1 | jq -r '.iss // empty' 2>/dev/null || true)"
  if ! dry; then
    uid="$(gcloud iam service-accounts describe "$FED_GCP_SA" --format='value(uniqueId)' ${GCP_PROJECT:+--project="$GCP_PROJECT"} 2>/dev/null || true)"
  fi
  [[ "$iss" == "https://accounts.google.com" ]] || ok=0
  [[ "$sub" =~ ^[0-9]+$ ]] || ok=0
  [[ -z "$uid" || "$sub" == "$uid" ]] || ok=0
  exchange_raw "$FED_GCP_CLIENT_ID" "$SUBJ"
  [[ "$ST" == 200 ]] || ok=0
  n="iss '$iss', sub '$sub' (unique ID ${uid:-unread}), exchange $ST $(msg). Minted with gcloud impersonation, the nearest to the metadata server's format=full"
  hverdict "$ok" "$n"
}

t_A16() {
  need_fed || return 0
  local ok=1 n="" src id
  src="$(fed_sources)"
  src="${src%% *}"
  id="$(fed_client "$src")"
  exchange_raw "$id" "a.b.c"
  { st_in "400 401 403" && err_body_ok; } || ok=0
  n="jwt=a.b.c: $ST $(msg)"
  if fed_subject "$src" "api.tailscale.com/other$RID"; then
    exchange_raw "$id" "$SUBJ"
    { st_in "400 401 403" && err_body_ok; } || ok=0
    n="$n; a $src token for another audience: $ST $(msg)"
  else
    n="$n; no token for another audience ($SUBJ_WHY)"
  fi
  verdict "$ok" "$n"
}

# ── 3. Tailnet ID and error codes ─────────────────────────────────────────

t_A17() {
  need_tok admin_read || return 0
  local ok=1 n="" t ep flipped first
  first="${TAILNET:0:1}"
  flipped="$(printf '%s' "$first" | tr '[:upper:][:lower:]' '[:lower:][:upper:]')${TAILNET:1}"
  for t in "TNoSuch1CNTRL" "$flipped"; do
    for ep in users "devices?fields=all" acl services; do
      api GET "/tailnet/$t/$ep" "$TOKEN" ""
      if [[ "$ST" != 404 ]] || ! err_body_ok; then
        ok=0
        n="$n, $t/$ep $ST"
      fi
    done
  done
  verdict "$ok" "expected 404 with {message} on users, devices, acl and services for TNoSuch1CNTRL and $flipped${n:+; got$n}"
}

t_A18() {
  need_tok admin_read || return 0
  local ok=1 own dash dns
  api GET "/tailnet/$TAILNET/users" "$TOKEN" ""
  own="$(json_get '[.users[]?.id] | sort | join(",")')"
  [[ "$ST" == 200 ]] || ok=0
  api GET "/tailnet/-/users" "$TOKEN" ""
  dash="$(json_get '[.users[]?.id] | sort | join(",")')"
  [[ "$ST" == 200 && "$dash" == "$own" ]] || ok=0
  local dash_st="$ST"
  dns="$(lab_dns || true)"
  if [[ -n "$dns" ]]; then
    api GET "/tailnet/$dns/users" "$TOKEN" ""
    st_in "400 404" || ok=0
    verdict "$ok" "/tailnet/-/users $dash_st, same users: $([[ "$dash" == "$own" ]] && echo yes || echo no); /tailnet/$dns/users $ST"
  else
    verdict "$ok" "/tailnet/-/users $dash_st, same users: $([[ "$dash" == "$own" ]] && echo yes || echo no); DNS name unknown, so not tried"
  fi
}

t_A19() {
  need ADMIN_CLIENT_ID DEVICE_A || return 0
  need_secret ADMIN || { r_skip "no admin secret"; return 0; }
  mint_raw "$ADMIN_CLIENT_ID" "$ADMIN_SECRET" "users:read"
  local tok="$MINT_TOKEN" ok=1 n="" ep
  for ep in "/tailnet/$TAILNET/devices" "/tailnet/$TAILNET/acl" "/tailnet/$TAILNET/services" "/device/$DEVICE_A/attributes"; do
    api GET "$ep" "$tok" ""
    { [[ "$ST" == 403 ]] && err_body_ok; } || ok=0
    n="$n, ${ep#/tailnet/"$TAILNET"} $ST '$(msg)'"
  done
  verdict "$ok" "users:read token:${n#,} (expected 403 with a message)"
}

t_A20() {
  need_tok admin_read || return 0
  local ok=1 n="" rtok="$TOKEN" dev
  for dev in "nNoSuch0CNTRL" ${OTHER_TAILNET_DEVICE:+"$OTHER_TAILNET_DEVICE"}; do
    api GET "/device/$dev?fields=all" "$rtok" ""
    [[ "$ST" == 404 ]] || ok=0
    n="$n; $dev: device $ST"
    api GET "/device/$dev/routes" "$rtok" ""
    [[ "$ST" == 404 ]] || ok=0
    n="$n, routes $ST"
    if token po_write; then
      api GET "/device/$dev/attributes" "$TOKEN" ""
      [[ "$ST" == 404 ]] || ok=0
      n="$n, attributes $ST"
      attr_patch "$(jq -n --arg d "$dev" --arg k "${KEY}_nx" --arg e "$(iso_in 300)" '{($d): {($k): {value: true, expiry: $e}}}')"
      [[ "$ST" == 404 ]] || ok=0
      n="$n, PATCH device-attributes $ST"
    fi
  done
  verdict "$ok" "${n#; } (expected 404 each)"
}

t_A21() {
  note "Collects every non-2xx body the run sees; judged at the end."
  defer
}

finish_A21() {
  if [[ -n "$SECRET_ECHO" ]]; then
    r_fail "a response quoted a secret:$SECRET_ECHO"
  elif [[ "$N_ERR" == 0 ]]; then
    r_skip "no non-2xx answers seen in $CALLS calls; run it with the oauth and errors areas"
  elif [[ -z "$BAD_ERR" ]]; then
    r_pass "all $N_ERR non-2xx bodies are JSON with a string message or error; none quoted a secret"
  else
    r_fail "of $N_ERR non-2xx bodies, these weren't {message} or {error}:$BAD_ERR"
  fi
}

t_A22() {
  need_tok admin_read || return 0
  api GET "/tailnet/$TAILNET/acl/" "$TOKEN" ""
  A22_SLASH="$ST"
  api GET "/tailnet/-/devices" "$TOKEN" ""
  A22_DASH="$ST"
  note "Redirects are never followed; every call of the run is judged at the end."
  defer
}

finish_A22() {
  if [[ "$N_3XX" == 0 ]]; then
    r_pass "no 3xx in $CALLS calls (/acl/ answered ${A22_SLASH:-not tried}, /tailnet/-/devices ${A22_DASH:-not tried})"
  else
    r_fail "$N_3XX redirects:$LIST_3XX"
  fi
}

t_A25() {
  note "Watches every 429 of the run (A91 bursts on purpose); judged at the end."
  defer
}

finish_A25() {
  if [[ "$N_429" == 0 ]]; then
    r_skip "no 429 seen in $CALLS calls; run it with --area rate to provoke one"
  elif [[ -z "$RA_BAD" ]]; then
    r_pass "$N_429 429s, Retry-After:$RA_SEEN"
  else
    r_fail "Retry-After that isn't seconds:$RA_BAD"
  fi
}

t_A26() {
  note "Records every 5xx of the run; it can't be provoked. Judged at the end."
  defer
}

finish_A26() {
  if [[ "$N_5XX" == 0 ]]; then
    r_skip "no 5xx seen in $CALLS calls (can't be provoked)"
  else
    r_pass "$N_5XX 5xx answers, each JSON or plain text:$LIST_5XX"
  fi
}

t_A27() {
  need FREE_TAILNET FREE_CLIENT_ID FREE_DEVICE || return 0
  need_secret FREE || { r_skip "no FREE secret"; return 0; }
  mint_raw "$FREE_CLIENT_ID" "$FREE_SECRET" "devices:posture_attributes"
  if [[ "$ST" != 200 ]] && ! dry; then
    r_fail "the FREE client's mint answered $ST $(msg)"
    return 0
  fi
  local tok="$MINT_TOKEN" saved="$TOKEN"
  TOKEN="$tok"
  attr_post "$FREE_DEVICE" "${KEY}_plan" true "$(iso_in 300)"
  local st="$ST" m
  m="$(msg)"
  if [[ "$st" == 200 ]]; then
    api DELETE "/device/$FREE_DEVICE/attributes/$(uri "${KEY}_plan")" "$tok" ""
  fi
  TOKEN="$saved"
  # The FREE device's key went through its own token, not po_write's cleanup.
  ATTRS=()
  verdict "$(st_in "400 402 403" && echo 1 || echo 0)" "HTTP $st '$m' on $FREE_TAILNET (expected 400, 402 or 403)"
}

# Every call's time is judged at the end, against the connector's 10 s timeout.
t_A28() {
  note "Every call's time is judged at the end."
  defer
}

finish_A28() {
  local ok
  ok="$(awk -v a="$MAX_SECS" 'BEGIN { print (a < 10) ? 1 : 0 }')"
  verdict "$ok" "slowest of $CALLS calls: $MAX_SECS_WHAT in ${MAX_SECS}s"
}

# ── 4. The policy file, as P0 reads it ────────────────────────────────────

# hujson_json FILE: FILE as plain JSON (comments and trailing commas cut).
hujson_json() {
  perl -0777 -pe '
    s{("(?:\\.|[^"\\])*")|//[^\n]*|/\*.*?\*/}{defined $1 ? $1 : ""}gse;
    s{("(?:\\.|[^"\\])*")|,(\s*[\]\}])}{defined $1 ? $1 : $2}gse;' "$1"
}

t_A32() {
  need_tok admin_read || return 0
  local ok=1 type keys_json keys_hujson
  api GET "/tailnet/$TAILNET/acl" "$TOKEN" "" "Accept: application/json"
  type="$(json_get 'type')"
  keys_json="$(json_get 'keys | map(ascii_downcase) | sort | join(",")')"
  [[ "$ST" == 200 && "$type" == object ]] || ok=0
  api GET "/tailnet/$TAILNET/acl" "$TOKEN" "" "Accept: application/hujson"
  hujson_json "$BODY" >"$WORK/hj.json"
  keys_hujson="$(jq -r 'keys | map(ascii_downcase) | sort | join(",")' "$WORK/hj.json" 2>/dev/null || echo unreadable)"
  [[ "$keys_json" == "$keys_hujson" ]] || ok=0
  verdict "$ok" "type $type, sections '$keys_json', the HuJSON's '$keys_hujson'"
}

t_A35() {
  need TAG_B PORT_B LOGIN DEVICE_A DEVICE_B_HOST || return 0
  need_snapshot || return 0
  local ok=1 n="" sec cap renamed=""
  pol_new
  # Rename each section to its other case, where the file has it once.
  for sec in grants:Grants ssh:SSH postures:Postures; do
    cap="${sec#*:}"
    sec="${sec%%:*}"
    if [[ "$(SEC="$sec" perl -0777 -ne 'BEGIN { $s = quotemeta $ENV{SEC} } $c = () = /"$s"\s*:/gi; print $c' "$P")" == 1 ]]; then
      SEC="$sec" CAP="$cap" perl -0777 -pi -e 'BEGIN { $s = quotemeta $ENV{SEC}; $c = $ENV{CAP} } s/"$s"(\s*:)/"$c"$1/i' "$P"
      renamed="$renamed $cap"
    fi
  done
  pol_add Postures "{" "\"${PST}_case\": {\"Assertions\": [\"${KEY}_case == true\"]}"
  pol_add Grants "[" "$(grant_to_b "$QL" "" ", \"SrcPosture\": [\"${PST}_case\"]")"
  validate "$P"
  [[ "$V_OK" == yes ]] || ok=0
  n="renamed:${renamed:- none}; validates: $V_OK $V_WHY"
  if [[ "$V_OK" != yes ]]; then verdict 0 "$n"; return 0; fi
  need_tok admin_write || return 0
  post_current "$P"
  [[ "$ST" == 200 ]] || ok=0
  n="$n; stored $ST"
  if [[ "$ok" == 1 ]] && baseline; then
    need_tok po_write || return 0
    attr_set_one "$DEVICE_A" "${KEY}_case" 600
    human_do "On device A, run: $(NC "$DEVICE_B_HOST" "$PORT_B")"
    if human_yn "Did it connect?"; then n="$n; A connects through the \"Postures\" posture"; else dry || ok=0; n="$n; A couldn't connect"; fi
    token po_write
    attr_unset_one "$DEVICE_A" "${KEY}_case"
    hverdict "$ok" "$n"
  else
    verdict "$ok" "$n; connection part not run"
  fi
}

# ── 5. Postures and device attributes ─────────────────────────────────────

t_A46() {
  need DEVICE_A || return 0
  need_tok po_write || return 0
  local ok=1 n="" k128 k129 key want e
  k128="${KEY}_$(printf 'k%.0s' {1..128})"
  k128="${k128:0:128}"
  k129="${KEY}_$(printf 'k%.0s' {1..129})"
  k129="${k129:0:129}"
  e="$(iso_in 300)"
  for key in "$k128:200" "$k129:400" "custom:p0-spec$RID:400" "custom:p0.spec$RID:400"; do
    want="${key##*:}"
    key="${key%:*}"
    attr_post "$DEVICE_A" "$key" true "$e"
    if [[ "$want" == 200 ]]; then [[ "$ST" == 200 ]] || ok=0; else [[ "$ST" == 400 ]] || ok=0; fi
    n="$n; ${key:0:24}... (${#key} chars): $ST"
  done
  verdict "$ok" "${n#; } (expected 200, 400, 400, 400)"
}

t_A47() {
  need DEVICE_A DEVICE_B || return 0
  need_tok po_write || return 0
  local ok=1 n="" e upper
  e="$(iso_in 300)"
  upper="custom:P0_SPEC$(printf '%s' "$RID" | tr '[:lower:]' '[:upper:]')_CASE"
  attr_post "$DEVICE_B" "$upper" true "$e"
  n="$upper on B: $ST"
  attr_post "$DEVICE_A" "${KEY}_case" true "$e"
  [[ "$ST" =~ ^4 ]] || ok=0
  n="$n; ${KEY}_case on A: $ST '$(msg)'"
  attr_post "$DEVICE_A" "${KEY}_type" '"yes"' "$e"
  n="$n; ${KEY}_type=\"yes\" on A: $ST"
  attr_post "$DEVICE_B" "${KEY}_type" true "$e"
  [[ "$ST" =~ ^4 ]] || ok=0
  n="$n; ${KEY}_type=true on B: $ST '$(msg)'"
  verdict "$ok" "$n (expected the second and fourth refused)"
}

t_A48() {
  need DEVICE_A || return 0
  need_tok po_write || return 0
  local ok=1 n="" e one two three four
  e="$(iso_in 300 .000)"
  one="${KEY}_one"; two="${KEY}_two"; three="${KEY}_three"; four="${KEY}_four"
  attr_track "$DEVICE_A" "$two"
  attr_track "$DEVICE_A" "$three"
  attr_track "$DEVICE_A" "$four"
  attr_post "$DEVICE_A" "$one" true "$e"
  [[ "$ST" == 200 ]] || ok=0
  attr_patch "$(jq -n --arg d "$DEVICE_A" --arg a "$one" --arg b "$two" --arg e "$e" '{($d): {($a): null, ($b): {value: true, expiry: $e}}}')"
  [[ "$ST" == 200 ]] || ok=0
  n="set and delete in one PATCH: $ST body '$(summary)'"
  attr_read "$DEVICE_A"
  [[ "$(attr_value "$one")" == absent && "$(attr_value "$two")" == true ]] || ok=0
  n="$n, then $one $(attr_value "$one"), $two $(attr_value "$two")"
  attr_patch "$(jq -n --arg d "$DEVICE_A" --arg k "$three" --arg e "$e" '{($d): {($k): {value: true, expiry: $e}}, "nNoSuch0CNTRL": {($k): {value: true, expiry: $e}}}')"
  [[ "$ST" =~ ^4 ]] || ok=0
  n="$n; with an unknown node: $ST"
  attr_read "$DEVICE_A"
  [[ "$(attr_value "$three")" == absent ]] || ok=0
  n="$n, A's $three $(attr_value "$three")"
  attr_patch "$(jq -n --arg d "$DEVICE_A" --arg k "$four" --arg bad "custom:p0-spec${RID}bad" --arg e "$e" '{($d): {($k): {value: true, expiry: $e}, ($bad): {value: true, expiry: $e}}}')"
  [[ "$ST" =~ ^4 ]] || ok=0
  n="$n; with an invalid key: $ST"
  attr_read "$DEVICE_A"
  [[ "$(attr_value "$four")" == absent ]] || ok=0
  n="$n, A's $four $(attr_value "$four")"
  dry && ok=1
  verdict "$ok" "$n"
}

t_A49() {
  need DEVICE_A || return 0
  need_tok po_write || return 0
  local ok=1 n="" frac k sent got
  for frac in .123 .000; do
    k="${KEY}_ms${frac#.}"
    sent="$(iso_in 300 "$frac")"
    attr_track "$DEVICE_A" "$k"
    attr_patch "$(jq -n --arg d "$DEVICE_A" --arg k "$k" --arg e "$sent" '{($d): {($k): {value: true, expiry: $e}}}')"
    [[ "$ST" == 200 ]] || ok=0
    attr_read "$DEVICE_A"
    got="$(attr_expiry "$k")"
    [[ "$(attr_type "$k")" == boolean && "$(attr_value "$k")" == true ]] || ok=0
    if [[ -n "$got" && "$(iso_ms "$got" 2>/dev/null)" == "$(iso_ms "$sent")" ]]; then
      n="$n; $frac: sent $sent, read back $got (same instant)"
    else
      ok=0
      n="$n; $frac: sent $sent, read back '${got:-none}' as $(attr_type "$k")"
    fi
  done
  dry && ok=1
  verdict "$ok" "${n#; }"
}

t_A50() {
  need DEVICE_A || return 0
  need_tok po_write || return 0
  local ok=1 n="" past k1 k2 i gone=""
  past="$(iso_in -60 .000)"
  k1="${KEY}_past"
  k2="${KEY}_past2"
  attr_track "$DEVICE_A" "$k1"
  attr_patch "$(jq -n --arg d "$DEVICE_A" --arg k "$k1" --arg e "$past" '{($d): {($k): {value: true, expiry: $e}}}')"
  local st1="$ST" m1
  m1="$(msg)"
  attr_post "$DEVICE_A" "$k2" true "$past"
  local st2="$ST"
  n="PATCH with an expiry a minute ago: $st1 $m1; POST: $st2 $(msg)"
  if [[ "$st1" != 200 ]]; then ok=0; fi
  attr_read "$DEVICE_A"
  n="$n; right after: $k1 $(attr_value "$k1"), $k2 $(attr_value "$k2")"
  if [[ "$st1" == 200 || "$st2" == 200 ]]; then
    say "Watching for Tailscale to drop the expired keys (up to 10 minutes)."
    for ((i = 0; i < 20; i++)); do
      attr_read "$DEVICE_A"
      if [[ "$(attr_value "$k1")" == absent && "$(attr_value "$k2")" == absent ]]; then gone="$((i * 30))"; break; fi
      dry && break
      wait_secs 30
    done
    if [[ -n "$gone" ]]; then n="$n; both gone after about ${gone}s"; else dry || ok=0; n="$n; still there after 10 minutes"; fi
  fi
  dry && ok=1
  verdict "$ok" "$n (the code needs 200 and the key gone within minutes; 400 breaks sibling grants)"
}

# posture_grant_file [SRC_JSON]: the original plus PST gating a grant from
# SRC (default the login) to B, into $P.
posture_grant_file() {
  pol_new
  pol_posture "$PST" "[\"$KEY == true\"]"
  pol_grant "$(grant_to_b "${1:-$QL}" "" ", \"srcPosture\": [\"$PST\"]")"
}

t_A51() {
  need DEVICE_A DEVICE_B_HOST TAG_B PORT_B LOGIN || return 0
  need_snapshot || return 0
  need_baseline || return 0
  need_tok po_write || return 0
  local ok=1 n="" set_at i gone=""
  attr_set_one "$DEVICE_A" "$KEY" 120
  set_at="$(now)"
  [[ "$ST" == 200 ]] || ok=0
  posture_grant_file
  need_tok admin_write || return 0
  post_current "$P"
  [[ "$ST" == 200 ]] || ok=0
  human_do "On device A, run: $(NC "$DEVICE_B_HOST" "$PORT_B")"
  if human_yn "Did it connect?"; then n="connects with the key set"; else dry || ok=0; n="doesn't connect with the key set"; fi
  say "Watching for Tailscale to remove the key after its 2-minute expiry (up to 12 minutes)."
  token po_write
  for ((i = 0; i < 24; i++)); do
    attr_read "$DEVICE_A"
    if [[ "$(attr_value "$KEY")" == absent ]]; then gone="$(now)"; break; fi
    dry && break
    wait_secs 30
  done
  if [[ -n "$gone" ]]; then
    n="$n; removed $((gone - set_at - 120))s after the expiry"
    [[ $((gone - set_at - 120)) -le 600 ]] || ok=0
  else
    dry || ok=0
    n="$n; still there 10 minutes after the expiry"
  fi
  human_do "On device A, run again: $(NC "$DEVICE_B_HOST" "$PORT_B")"
  if human_yn "Did it connect?"; then ok=0; n="$n; still connects after the removal"; else n="$n; no longer connects"; fi
  dry && ok=1
  hverdict "$ok" "$n"
}

t_A52() {
  need DEVICE_A DEVICE_B_HOST TAG_B PORT_B LOGIN || return 0
  need_snapshot || return 0
  need_baseline || return 0
  need_tok po_write || return 0
  local ok=1 t0 secs
  attr_set_one "$DEVICE_A" "$KEY" 3600
  posture_grant_file
  need_tok admin_write || return 0
  post_current "$P"
  human_do "On device A, in another terminal, start: while nc -vz -w 2 $DEVICE_B_HOST $PORT_B; do sleep 1; done" "Press Enter once it's connecting every second."
  token po_write
  attr_unset_one "$DEVICE_A" "$KEY"
  t0="$(now)"
  if human_event "The loop stops when a connection fails. Press Enter the moment it stops."; then
    secs=$(($(now) - t0))
    [[ "$secs" -lt 60 ]] || ok=0
    hverdict "$ok" "the posture stopped matching ${secs}s after the delete (expected under a minute)"
  else
    hverdict 0 "A kept connecting after the key was deleted"
  fi
}

t_A53() {
  need DEVICE_A || return 0
  need_tok po_write || return 0
  api DELETE "/device/$DEVICE_A/attributes/$(uri "${KEY}_never")" "$TOKEN" ""
  verdict "$(st_in "404 200" && echo 1 || echo 0)" "HTTP $ST $(msg) (404 expected, 200 also fine; anything else fails the install check)"
}

t_A54() {
  need DEVICE_A PO_CLIENT_ID || return 0
  need_secret PO || { r_skip "no PO secret"; return 0; }
  local ok=1 n="" saved="$TOKEN"
  mint_raw "$PO_CLIENT_ID" "$PO_SECRET" "devices:posture_attributes"
  [[ "$ST" == 200 ]] || ok=0
  n="mint $ST, scope '$MINT_SCOPE'"
  TOKEN="$MINT_TOKEN"
  attr_read "$DEVICE_A"
  [[ "$ST" == 200 ]] || ok=0
  n="$n; read $ST"
  attr_set_one "$DEVICE_A" "${KEY}_only" 300
  [[ "$ST" == 200 ]] || ok=0
