# ── 8. Rate limits ────────────────────────────────────────────────────────

t_A91() {
  need DEVICE_A || return 0
  local i started limited="" n=""
  gate "Send two bursts: 30 device listings and $RATE_BURST attribute PATCHes?" || { r_skip "not allowed"; return 0; }
  need_tok po_read || return 0
  started="$(now)"
  for ((i = 1; i <= 30; i++)); do
    api GET "/tailnet/$TAILNET/devices?fields=all" "$TOKEN" ""
    if [[ "$ST" == 429 ]]; then limited="listing $i after $(($(now) - started))s, Retry-After '$(header retry-after)'"; break; fi
  done
  n="30 listings in $(($(now) - started))s"
  if [[ -z "$limited" ]]; then
    need_tok po_write || return 0
    started="$(now)"
    for ((i = 1; i <= RATE_BURST; i++)); do
      attr_set_one "$DEVICE_A" "${KEY}_burst" 300
      if [[ "$ST" == 429 ]]; then limited="attribute PATCH $i after $(($(now) - started))s, Retry-After '$(header retry-after)'"; break; fi
    done
    n="$n; $RATE_BURST PATCHes in $(($(now) - started))s"
  fi
  if [[ -n "$limited" ]]; then r_fail "429 at $limited"; else r_pass "no 429: $n"; fi
}

# ── 9. Revoke and grant timing ────────────────────────────────────────────
#
# One flow records A92 to A95: the customer's posture-gated grant and SSH
# rule, then set the key, hold a TCP connection and an SSH session, and
# delete the key as the connector does at revoke.

t_A92() { revoke_flow; }
t_A93() { revoke_flow; }
t_A94() { revoke_flow; }
t_A95() { revoke_flow; }

want_id() {
  local i
  i="$(idx_of "$1")"
  is_selected "$i"
}

# revoke_round: the timings into R_GRANT, R_NEWFAIL, R_TCP, R_SSH.
revoke_round() {
  local t0
  R_GRANT="never"
  R_NEWFAIL="never"
  R_TCP="?"
  R_SSH="?"
  human_do "On device A, in a new terminal, start: while ! nc -vz -w 2 $DEVICE_B_HOST $PORT_B; do sleep 1; done" "Press Enter, then watch that loop."
  token po_write
  attr_set_one "$DEVICE_A" "$KEY" 3600
  t0="$(now)"
  [[ "$ST" == 200 ]] || dry || { warn "the grant answered $ST $(msg)"; return 1; }
  human_event "Press Enter the moment the loop connects." && R_GRANT="$(($(now) - t0))s"
  human_do "Open and hold, in one terminal: nc $DEVICE_B_HOST $PORT_B"
  human_do "Open and hold, in another: tailscale ssh $SSH_USER@$DEVICE_B_HOST" "Press Enter when both are open; the revoke happens then."
  token po_write
  attr_unset_one "$DEVICE_A" "$KEY"
  t0="$(now)"
  human_do "Start a new loop on A: while nc -vz -w 2 $DEVICE_B_HOST $PORT_B; do sleep 1; done (it ends when a new connection fails)" "Press Enter to start timing."
  human_event "Press Enter the moment that loop ends." && R_NEWFAIL="$(($(now) - t0))s"
  local left=$((60 - ($(now) - t0)))
  if [[ "$left" -gt 0 ]]; then say "Waiting ${left}s, so a minute has passed since the revoke."; wait_secs "$left"; fi
  if human_yn "Type a line into the held nc: does B still receive it?"; then R_TCP=kept; else R_TCP=cut; fi
  # B ends the session at once, but its "Access revoked" can't reach A once
  # the revoke drops their traffic, so A's ssh freezes rather than closing.
  # B's tailscaled log ("session no longer valid per new SSH policy") is the
  # proof.
  human_do "On B, read tailscaled's log: journalctl -u tailscaled --since '-5 min' | grep -i 'no longer valid'"
  if human_yn "Does it show B closing the SSH session at the revoke (A's ssh window may freeze rather than close)?"; then R_SSH="ended"; else R_SSH="still open"; fi
  settle
}

revoke_flow() {
  [[ "$REVOKE_DONE" == 1 ]] && return 0
  REVOKE_DONE=1
  local id missing="" v why=""
  for v in DEVICE_A DEVICE_B_HOST TAG_B PORT_B LOGIN SSH_USER; do [[ -n "${!v:-}" ]] || missing="$missing $v"; done
  if [[ -n "$missing" ]]; then
    why="setup missing:$missing"
  elif ! snapshot; then
    why="$TOKEN_WHY"
  elif ! baseline; then
    why="the lab policy already lets A reach B, so a connection proves nothing"
  fi
  if [[ -n "$why" ]]; then
    for id in A92 A93 A94 A95; do
      if want_id "$id"; then res "$id" SKIP "$why"; fi
    done
    return 0
  fi
  # The customer's posture-gated grant and SSH rule. P0 only sets the key.
  local po_grant="not run" po_fail="not run" po_tcp="not run" po_ssh="not run"
  pol_new
  pol_posture "$PST" "[\"$KEY == true\"]"
  pol_grant "$(grant_to_b "$QL" "" ", \"srcPosture\": [\"$PST\"]")"
  pol_grant "$(grant_to_b "$QL" 22 ", \"srcPosture\": [\"$PST\"]")"
  pol_ssh "$(ssh_rule "$QL" ", \"srcPosture\": [\"$PST\"]")"
  if token admin_write && token po_write; then
    token admin_write
    post_current "$P"
    if [[ "$ST" == 200 ]] || dry; then
      say "Set the key, then revoke by deleting it."
      if revoke_round; then po_grant="$R_GRANT"; po_fail="$R_NEWFAIL"; po_tcp="$R_TCP"; po_ssh="$R_SSH"; fi
    fi
  fi
  if want_id A92; then
    if [[ "$po_fail" == never ]]; then
      res A92 FAIL "new connections after revoke: $po_fail"
    else
      res A92 HUMAN "new connections failed after: $po_fail"
    fi
  fi
  want_id A93 && res A93 HUMAN "open TCP across a revoke: $po_tcp"
  if want_id A94; then
    if [[ "$po_ssh" == ended ]]; then
      res A94 HUMAN "the SSH session ended at revoke"
    else
      res A94 FAIL "SSH session at revoke: $po_ssh"
    fi
  fi
  if want_id A95; then
    if [[ "$po_grant" == never ]]; then
      res A95 FAIL "grant took effect: $po_grant"
    else
      res A95 HUMAN "grant took effect after: $po_grant"
    fi
  fi
}

# ══════════════════════════════════════════════════════════════════════════
# Running
# ══════════════════════════════════════════════════════════════════════════

run_check() {
  local i="$1"
  CUR_ID="${C_IDS[$i]}"
  printf '\n  %s%s%s %s %s(%s)%s\n' "$BOLD" "$CUR_ID" "$RESET" "${C_CLAIMS[$i]}" "$DIM" "$(kind_name "${C_KINDS[$i]}")" "$RESET"
  if [[ "$UNATTENDED" == 1 && "${C_KINDS[$i]}" == human ]]; then
    r_skip "needs a person (unattended run)"
    return 0
  fi
  NEEDED_PERSON=0
  local first_result=${#R_IDS[@]} r
  "t_$CUR_ID" || true
  # A check that reached a person's step in an unattended run has no real
  # answer for that step, so it can't PASS or FAIL.
  if [[ "$NEEDED_PERSON" == 1 ]]; then
    for ((r = first_result; r < ${#R_IDS[@]}; r++)); do
      if [[ "${R_IDS[$r]}" == "$CUR_ID" ]]; then
        R_NOTES[r]="part of it needs a person (unattended run; was ${R_RES[$r]}): ${R_NOTES[$r]}"
        R_RES[r]=SKIP
      fi
    done
    has_result "$CUR_ID" || r_skip "part of it needs a person (unattended run)"
  fi
  if ! has_result "$CUR_ID" && ! in_list "$CUR_ID" "$DEFERRED"; then
    res "$CUR_ID" FAIL "the check ended without a verdict (last call HTTP $ST)"
  fi
  settle
}

# sort_results puts the recorded results in check order (A01 first).
sort_results() {
  local c r ids=() rs=() ns=()
  for ((c = 0; c < ${#C_IDS[@]}; c++)); do
    for ((r = 0; r < ${#R_IDS[@]}; r++)); do
      if [[ "${R_IDS[$r]}" == "${C_IDS[$c]}" ]]; then
        ids+=("${R_IDS[$r]}")
        rs+=("${R_RES[$r]}")
        ns+=("${R_NOTES[$r]}")
      fi
    done
  done
  [[ ${#ids[@]} -gt 0 ]] || return 0
  R_IDS=("${ids[@]}")
  R_RES=("${rs[@]}")
  R_NOTES=("${ns[@]}")
}

# write_results [STATUS]: the results file, ready to paste into INT-666.
write_results() {
  sort_results
  dry && return 0
  local i idx id status="${1:-complete}" pass=0 fail=0 human=0 skip=0
  for ((i = 0; i < ${#R_IDS[@]}; i++)); do
    case "${R_RES[$i]}" in
      PASS) pass=$((pass + 1)) ;;
      FAIL) fail=$((fail + 1)) ;;
      HUMAN) human=$((human + 1)) ;;
      SKIP) skip=$((skip + 1)) ;;
    esac
  done
  row() {
    local j="$1" c
    c="$(idx_of "${R_IDS[$j]}")"
    printf '| %s | %s | %s | %s |\n' "${R_IDS[$j]}" "${C_CLAIMS[$c]//|//}" "${R_RES[$j]}" "${R_NOTES[$j]}"
  }
  {
    printf '# Tailscale spec test results\n\n'
    printf -- '- Run %s on tailnet %s, %s to %s (UTC), %s.\n' "$RID" "$TAILNET" "$STARTED" "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$status"
    printf -- '- Script: services/p0-connector-tailscale/scripts/admin-test.sh at %s.\n' "$(git -C "$SCRIPT_DIR" rev-parse --short HEAD 2>/dev/null || echo unknown)"
    printf -- '- %s checks: %s PASS, %s FAIL, %s HUMAN, %s SKIP. %s API calls.\n\n' "${#R_IDS[@]}" "$pass" "$fail" "$human" "$skip" "$CALLS"
    local risky=""
    for id in $RISKY; do
      for ((i = 0; i < ${#R_IDS[@]}; i++)); do
        if [[ "${R_IDS[$i]}" == "$id" && "${R_RES[$i]}" == FAIL ]]; then
          idx="$(idx_of "$id")"
          risky="$risky- **$id FAIL: ${C_CLAIMS[$idx]}.** ${R_NOTES[$i]}"$'\n'
        fi
      done
    done
    if [[ -n "$risky" ]]; then printf '**Riskiest assumptions that failed**\n\n%s\n' "$risky"; fi
    printf '## INT-666 checklist\n\n| ID | Claim | Result | Note |\n| --- | --- | --- | --- |\n'
    for ((i = 0; i < ${#R_IDS[@]}; i++)); do
      idx="$(idx_of "${R_IDS[$i]}")"
      [[ -n "${C_TAGS[$idx]}" ]] && row "$i"
    done
    printf '\n## Every check\n\n| ID | Claim | Result | Note |\n| --- | --- | --- | --- |\n'
    for ((i = 0; i < ${#R_IDS[@]}; i++)); do
      idx="$(idx_of "${R_IDS[$i]}")"
      [[ -z "${C_TAGS[$idx]}" ]] && row "$i"
    done
    printf '\nThe call log, bodies redacted, is %s.\n' "$(basename "$LOG")"
  } >"$RESULTS"
  chmod 600 "$RESULTS"
  RESULTS_WRITTEN=1
}

print_table() {
  local i idx id claim color
  sort_results
  for id in $RISKY; do
    for ((i = 0; i < ${#R_IDS[@]}; i++)); do
      if [[ "${R_IDS[$i]}" == "$id" && "${R_RES[$i]}" == FAIL ]]; then
        idx="$(idx_of "$id")"
        printf '  %s%s%s FAIL (riskiest): %s. %s%s\n' "$BOLD" "$RED" "$id" "${C_CLAIMS[$idx]}" "${R_NOTES[$i]}" "$RESET"
      fi
    done
  done
  printf '\n  %s%-4s  %-6s  %-58s  %s%s\n' "$BOLD" "ID" "Result" "Claim" "Note" "$RESET"
  for ((i = 0; i < ${#R_IDS[@]}; i++)); do
    idx="$(idx_of "${R_IDS[$i]}")"
    claim="${C_CLAIMS[$idx]}"
    [[ ${#claim} -gt 58 ]] && claim="${claim:0:55}..."
    case "${R_RES[$i]}" in
      PASS) color="$GREEN" ;;
      FAIL) color="$RED" ;;
      HUMAN) color="$BLUE" ;;
      *) color="$DIM" ;;
    esac
    printf '  %-4s  %s%-6s%s  %-58s  %s\n' "${R_IDS[$i]}" "$color" "${R_RES[$i]}" "$RESET" "$claim" "${R_NOTES[$i]:0:110}"
  done
}

on_exit() {
  local code=$?
  trap '' INT TERM
  set +e
  forget_tokens
  settle
  if ! dry && [[ "$RESULTS_WRITTEN" != 1 && ${#R_IDS[@]} -gt 0 ]]; then
    write_results "interrupted"
    printf '\n  Partial results: %s\n' "$RESULTS"
  fi
  ADMIN_SECRET=""
  PO_SECRET=""
  RO_SECRET=""
  ALL_SECRET=""
  FREE_SECRET=""
  rm -rf "$WORK"
  exit "$code"
}
trap on_exit EXIT
trap 'exit 130' INT
trap 'exit 143' TERM

# ══════════════════════════════════════════════════════════════════════════
# Setup (--setup): the person creates the two OAuth clients in the console,
# and setup finds everything else through the API, then writes each value
# to the env file. It only reads from Tailscale. The secrets stay in shell
# variables for this run and are never written or printed.
# ══════════════════════════════════════════════════════════════════════════

S_TOK=""
S_USERS="$WORK/s_users.json"
S_DEVICES="$WORK/s_devices.json"
S_ACL="$WORK/s_acl.json"
S_SERVICES="$WORK/s_services.json"
S_CHOICES="$WORK/s_choices.tsv"
LOCAL_NODE=""
LOCAL_LOGIN=""

# s_put KEY VALUE sets KEY and writes it to the env file. A dry run says
# what it would write.
s_put() {
  printf -v "$1" '%s' "$2"
  if dry; then
    note "(dry run, would write) $1=$2"
  else
    write_env "$1" "$2"
  fi
}

# s_keep KEY... writes each KEY that has a value.
s_keep() {
  local k
  for k in "$@"; do
    if [[ -n "${!k:-}" ]]; then s_put "$k" "${!k}"; fi
  done
  return 0
}

# s_ask KEY PROMPT [DEFAULT] asks for KEY, offering the env file's value or
# else DEFAULT. A dry run asks nothing and keeps the placeholder.
s_ask() {
  local k="$1" prompt="$2" def="${3:-}" cur
  if dry; then
    note "(dry run, would ask) $prompt"
    return 0
  fi
  cur="$(_existing "$k" || true)"
  if [[ -z "$cur" && -n "$def" ]]; then prompt="$prompt [Enter for $def]"; fi
  ask "$k" "$prompt"
  if [[ -z "${!k}" ]]; then printf -v "$k" '%s' "$def"; fi
  return 0
}

# s_choose VAR PROMPT [PREFERRED] lists $S_CHOICES (value, tab, label) by
# number and sets VAR to the one picked, or to what the person types.
# PREFERRED, or a lone choice, is the Enter default. Enter with no default
# leaves VAR empty.
s_choose() {
  local var="$1" prompt="$2" want="${3:-}" n def="" reply hint
  n="$(grep -c . "$S_CHOICES" 2>/dev/null || true)"
  n="${n:-0}"
  if [[ -n "$want" ]]; then
    def="$(awk -F'\t' -v w="$want" '$1 == w { print NR; exit }' "$S_CHOICES" 2>/dev/null || true)"
  fi
  if [[ -z "$def" && "$n" == 1 ]]; then def=1; fi
  if dry; then
    note "(dry run, would list what the API returned and ask) $prompt"
    return 0
  fi
  if [[ "$n" -gt 0 ]]; then
    awk -F'\t' '{ printf "    %2d) %s\n", NR, $2 }' "$S_CHOICES"
    hint="1 to $n, or type it"
  else
    hint="type it, or Enter to leave it blank"
  fi
  while :; do
    printf '  %s%s%s %s[%s%s]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$hint" "${def:+, Enter for $def}" "$RESET"
    reply=""
    read -r reply || true
    if [[ -z "$reply" ]]; then reply="$def"; fi
    if [[ -z "$reply" ]]; then
      printf -v "$var" '%s' ""
      return 0
    fi
    if [[ "$reply" =~ ^[0-9]+$ ]]; then
      if [[ "$reply" -ge 1 && "$reply" -le "$n" ]]; then
        printf -v "$var" '%s' "$(sed -n "${reply}p" "$S_CHOICES" | cut -f1)"
        return 0
      fi
      warn "Pick a number from 1 to $n."
      continue
    fi
    printf -v "$var" '%s' "$reply"
    return 0
  done
}

# s_missing GRANTED REQUIRED: the REQUIRED scopes GRANTED doesn't cover. A
# write scope covers its :read, and all covers everything.
s_missing() {
  local s out=""
  for s in $2; do
    if in_list "$s" "$1" || in_list all "$1"; then continue; fi
    if [[ "$s" == *:read ]] && { in_list "${s%:read}" "$1" || in_list all:read "$1"; }; then continue; fi
    out="$out $s"
  done
  printf '%s' "${out# }"
}

# s_scope_steps SCOPES: one console line per scope.
s_scope_steps() {
  local s
  for s in $1; do
    case "$s" in
      policy_file) note "    Policy File: Write ($s)" ;;
      policy_file:read) note "    Policy File: Read ($s)" ;;
      users:read) note "    Users: Read ($s)" ;;
      devices:core:read) note "    Devices, Core: Read ($s)" ;;
      devices:posture_attributes) note "    Devices, Posture Attributes: Write ($s)" ;;
      devices:routes:read) note "    Devices, Routes: Read ($s)" ;;
      services:read) note "    Services: Read ($s)" ;;
      *) note "    $s" ;;
    esac
  done
}

# s_client CLIENT LABEL REQUIRED asks for CLIENT's ID and secret, mints a
# token with no scope the way the connector does, and writes the ID and the
# scopes the token response lists. The secret is dropped once it has minted.
s_client() {
  local c="$1" label="$2" required="$3" id_var="${1}_CLIENT_ID" sec_var="${1}_SECRET" tries=0 granted missing bad=0
  while :; do
    tries=$((tries + 1))
    s_ask "$id_var" "The $label client's ID:"
    if dry; then
      printf -v "$sec_var" '%s' "dry-run-secret"
      note "(dry run, would ask, hidden) the $label client's secret"
    else
      ask_secret "$sec_var" "Its secret (hidden, kept in memory for this run only, never written):"
    fi
    add_secret "${!sec_var}"
    if [[ -n "${!id_var}" && -n "${!sec_var}" ]]; then
      mint_raw "${!id_var}" "${!sec_var}"
      if dry || [[ "$ST" == 200 && -n "$MINT_TOKEN" ]]; then break; fi
      warn "Tailscale refused it: HTTP $ST $(msg). Copy the ID and secret again from the Credential created page. If you closed it, make a new client: the secret shows only once."
    else
      warn "Both the client ID and its secret are needed."
    fi
    printf -v "$sec_var" '%s' ""
    [[ "$tries" -lt 3 ]] || die "Setup stopped after 3 tries. Anything already written stays in $ENV_FILE; run --setup again."
  done
  printf -v "$sec_var" '%s' ""
  granted="$MINT_SCOPE"
  if dry; then granted="$required"; fi
  if [[ "$c" == ADMIN ]]; then S_TOK="$MINT_TOKEN"; fi
  say "The token's scope field: ${granted:-empty}"
  missing="$(s_missing "$granted" "$required")"
  if [[ -n "$missing" ]]; then
    bad=1
    warn "This client lacks $missing, which the $label client needs."
  fi
  if [[ "$c" == PO ]] && { in_list policy_file "$granted" || in_list all "$granted"; }; then
    bad=1
    warn "This client can write the policy file. The connector refuses such a credential, so set Policy File to Read."
  fi
  if [[ "$bad" == 1 ]] && confirm "Make a new $label client with the scopes above and enter it instead?"; then
    s_client "$@"
    return 0
  fi
  s_put "$id_var" "${!id_var}"
  s_put "${c}_SCOPES" "$granted"
}

# s_fetch PATH OUT [HEADER...] reads PATH with the admin client's token into OUT.
s_fetch() {
  local path="$1" out="$2"
  shift 2
  api GET "$path" "$S_TOK" "" "$@"
  cp "$BODY" "$out"
  if dry || [[ "$ST" == 200 ]]; then return 0; fi
  warn "GET $path answered HTTP $ST: $(msg)"
  return 1
}

# s_device_field NODE_ID JQ: one field of a listed device.
s_device_field() {
  jq -r --arg n "$1" "[.devices[]? | select(.nodeId == \$n) | $2][0] // empty" "$S_DEVICES" 2>/dev/null || true
}

# s_local: this machine's node ID and login, from the tailscale CLI if any.
s_local() {
  local ts="" sj
  dry && return 0
  if command -v tailscale >/dev/null 2>&1; then
    ts=tailscale
  elif [[ -x /Applications/Tailscale.app/Contents/MacOS/Tailscale ]]; then
    ts=/Applications/Tailscale.app/Contents/MacOS/Tailscale
  fi
  [[ -n "$ts" ]] || return 0
  sj="$("$ts" status --json 2>/dev/null || true)"
  LOCAL_NODE="$(printf '%s' "$sj" | jq -r '.Self.ID // empty' 2>/dev/null || true)"
  LOCAL_LOGIN="$(printf '%s' "$sj" | jq -r '(.Self.UserID | tostring) as $u | .User[$u].LoginName // empty' 2>/dev/null || true)"
  return 0
}

# s_skips KEY: what a blank KEY means for the run.
s_skips() {
  case "$1" in
    LAB_TAILNET | TAILNET) printf 'required: the test refuses to start' ;;
    LOGIN | DEVICE_A | DEVICE_B | DEVICE_B_HOST | TAG_B | PORT_B | ADMIN_CLIENT_ID | PO_CLIENT_ID)
      printf 'required: the test asks for it at the start' ;;
    SSH_USER) printf 'required: the test asks for it; A61 A92 to A95 need it' ;;
    DEVICE_C | ROUTER_SUBNET) printf 'SKIPs A65' ;;
    SERVICE_NAME) printf 'optional: A82 checks only the shape without it' ;;
    RO_CLIENT_ID) printf 'SKIPs A10' ;;
    ALL_CLIENT_ID) printf 'optional: A10 checks all:read only' ;;
    FED_AWS_CLIENT_ID | FED_AWS_ROLE_ARN) printf 'SKIPs A14, and A11 to A13 and A16 unless GCP is set' ;;
    FED_GCP_CLIENT_ID | FED_GCP_SA) printf 'SKIPs A15, and A11 to A13 and A16 unless AWS is set' ;;
    SHARED_DEVICE) printf 'SKIPs A70' ;;
    FREE_TAILNET | FREE_CLIENT_ID | FREE_DEVICE) printf 'SKIPs A27' ;;
    SPARE_DEVICE) printf 'SKIPs A75' ;;
    TAILNET_DNS) printf 'optional: derived from a device name' ;;
    ADMIN_SCOPES) printf 'optional: the admin list is assumed' ;;
    PO_SCOPES | FED_AWS_SCOPES | FED_GCP_SCOPES) printf 'optional: the connector'"'"'s list is assumed' ;;
    OTHER_TAILNET_DEVICE) printf 'optional: A20 tries a made-up node ID only' ;;
    *) printf 'optional' ;;
  esac
}

# s_summary prints every variable: set, or blank and what that means.
s_summary() {
  local entry k v
  if dry; then note "$ENV_FILE as it stands (a dry run writes nothing):"; fi
  printf '\n  %s%-22s %-6s %s%s\n' "$BOLD" "Variable" "State" "Value, or what blank means" "$RESET"
  for entry in "${ENV_KEYS[@]}"; do
    k="${entry%%|*}"
    v="$(_existing "$k" || true)"
    if [[ -n "$v" ]]; then
      if [[ ${#v} -gt 60 ]]; then v="${v:0:57}..."; fi
      printf '  %-22s %sset%s    %s\n' "$k" "$GREEN" "$RESET" "$v"
    else
      printf '  %-22s %sblank%s  %s\n' "$k" "$YELLOW" "$RESET" "$(s_skips "$k")"
    fi
  done
}

# s_extras offers the optional extras, each defaulting to no.
s_extras() {
  if dry; then
    note "(dry run, would ask) Set up the optional extras now? Each one defaults to no."
    return 0
  fi
  say "Optional extras each need more setup. Without them, these checks SKIP:"
  note "  federated AWS identity: A14; federated GCP identity: A15; with neither, A11 to A13 and A16 too"
  note "  read-only client (all:read): A10; all-scope client: part of A10"
  note "  second tailnet on the Personal plan: A27"
  note "  a device shared in from another tailnet: A70; a spare device: A75"
  confirm "Set up any of them now?" || return 0

  if confirm "A read-only client and an all-scope client (A10)?"; then
    open_page "$CONSOLE/settings/trust-credentials"
    step "Make an OAuth client with every scope set to Read (all:read), and another with every scope set to Write (all). The test asks for their secrets when it runs."
    s_ask RO_CLIENT_ID "The read-only client's ID:"
    s_ask ALL_CLIENT_ID "The all-scope client's ID (Enter to skip):"
    s_keep RO_CLIENT_ID ALL_CLIENT_ID
  fi

  if confirm "A federated identity for AWS (A11 to A14, A16)?"; then
    open_page "$CONSOLE/settings/trust-credentials"
    step "Select Credential, then OpenID Connect. Issuer: your AWS account's outbound identity federation issuer (Custom issuer). Subject: the ARN of a throwaway IAM role your SSO role may assume."
    step "Give it the connector's scopes (the connector client's list above), then Generate credential and copy the client ID."
    s_ask FED_AWS_CLIENT_ID "The AWS federated identity's client ID:"
    s_ask FED_AWS_ROLE_ARN "The role ARN you used as the subject:"
    s_ask SPEC_AWS_PROFILE "The AWS CLI profile to sign in with (Enter for the default chain):"
    s_ask SPEC_AWS_REGION "An AWS region for STS:" us-west-2
    s_keep FED_AWS_CLIENT_ID FED_AWS_ROLE_ARN SPEC_AWS_PROFILE SPEC_AWS_REGION
  fi

  if confirm "A federated identity for GCP (A11 to A13, A15, A16)?"; then
    open_page "$CONSOLE/settings/trust-credentials"
    step "Select Credential, then OpenID Connect. Issuer: Google (https://accounts.google.com). Subject: the service account's unique ID, the number on its details page in IAM, Service accounts."
    step "Give it the connector's scopes (the connector client's list above), then Generate credential and copy the client ID. You need roles/iam.serviceAccountTokenCreator on that service account."
    s_ask FED_GCP_CLIENT_ID "The GCP federated identity's client ID:"
    s_ask FED_GCP_SA "The service account's email:"
    s_ask GCP_PROJECT "Its GCP project (Enter to skip):"
    s_keep FED_GCP_CLIENT_ID FED_GCP_SA GCP_PROJECT
  fi

  if confirm "A second tailnet on the Personal plan (A27, and A20's other-tailnet device)?"; then
    step "Sign in to a second tailnet on the free Personal plan. In its Settings, Trust credentials, make an OAuth client with Devices, Posture Attributes: Write."
    step "Its Tailnet ID is in its Settings, General. Its devices' node IDs are in each machine's details."
    s_ask FREE_TAILNET "The second tailnet's Tailnet ID:"
    s_ask FREE_CLIENT_ID "Its OAuth client's ID:"
    s_ask FREE_DEVICE "The node ID of one of its devices:"
    s_keep FREE_TAILNET FREE_CLIENT_ID FREE_DEVICE
    if [[ -n "$FREE_DEVICE" ]]; then s_put OTHER_TAILNET_DEVICE "$FREE_DEVICE"; fi
  fi

  if confirm "A device shared in from another tailnet (A70)?"; then
    jq -r '.devices[]? | select(.isExternal == true) | [.nodeId, "\(.name)  \(.nodeId)"] | @tsv' "$S_DEVICES" >"$S_CHOICES" 2>/dev/null || : >"$S_CHOICES"
    if [[ ! -s "$S_CHOICES" ]]; then
      step "None is shared in yet. In the other tailnet, open a machine's menu, Share, and send the invite to $LOGIN. Accept it here, then type its node ID."
    fi
    s_choose SHARED_DEVICE "The shared-in device:"
    s_keep SHARED_DEVICE
  fi

  if confirm "A spare device you can sign out and back in as another user (A75)?"; then
    jq -r --arg a "$DEVICE_A" --arg b "$DEVICE_B" '.devices[]? | select(.isExternal != true and .nodeId != $a and .nodeId != $b) | [.nodeId, "\(.name | split(".")[0])  \(.user // "")  \(.nodeId)"] | @tsv' "$S_DEVICES" >"$S_CHOICES" 2>/dev/null || : >"$S_CHOICES"
    s_choose SPARE_DEVICE "The spare device:"
    s_keep SPARE_DEVICE
  fi
  return 0
}

run_setup() {
  TOTAL_STAGES=8
  LOG=/dev/null
  if dry; then
    _clear() { :; }
    printf '\n%s%s  Tailscale spec test setup, dry run%s\n' "$BOLD" "$BLUE" "$RESET"
    note "No call is made, nothing is asked or written. Placeholders stand in for answers."
  else
    mkdir -p "$OUT_DIR"
    if [[ ! -f "$ENV_FILE" ]]; then
      cp "$SCRIPT_DIR/admin-test.env.example" "$ENV_FILE"
      chmod 600 "$ENV_FILE"
    fi
    banner "Tailscale spec test setup"
  fi

  # ── 1. What you need ──
  stage "What you need"
  say "This fills in $ENV_FILE for the Tailscale spec test. It only reads from"
  say "Tailscale, and writes IDs to that file. Secrets stay in memory for this run."
  printf '\n'
  step "A throwaway lab tailnet on a Premium plan or Premium trial, where you're an Admin or Owner."
  warn "The test rewrites the lab's policy file and sets device attributes. It restores each one, but never point it at a tailnet people use."
  step "Device A: this machine, on the lab tailnet, signed in as you, with no tags."
  step "Device B: a second machine on the lab tailnet, with a tag, Tailscale SSH on (tailscale set --ssh) and something listening on a TCP port."
  step "Two OAuth clients: an admin client, the test's own, which writes test postures into the lab policy file, and the connector's client, with exactly the connector's scopes. You make them next."
  step "The Tailnet ID: Settings, General, under Tailnet ID. It starts with T and ends with CNTRL; it's not the DNS name (tail....ts.net) or the Legacy ID. Setup finds it or asks you to paste it."
  dry || pause "Press Enter to make the first OAuth client."

  # ── 2. Admin client ──
  stage "The admin OAuth client"
  open_page "$CONSOLE/settings/trust-credentials"
  step "On Settings, Trust credentials, select the Credential button, then OAuth."
  step "If it asks for a description, enter: P0 spec test admin."
  say "Only the spec test uses this client, to set up the lab. The connector never gets Policy File: Write."
  step "Set exactly these scopes, and nothing else:"
  s_scope_steps "$ADMIN_REQUIRED"
  step "Select Generate credential. On the Credential created page, copy the client ID and the secret (it shows only once), then select Done."
  s_client ADMIN admin "$ADMIN_REQUIRED"

  # ── 3. The connector's client ──
  stage "The connector's OAuth client"
  open_page "$CONSOLE/settings/trust-credentials"
  step "Select the Credential button again, then OAuth."
  step "If it asks for a description, enter: P0 spec test connector."
  step "Set exactly these scopes. Policy File is Read here, not Write:"
  s_scope_steps "$REQUIRED_SCOPES"
  step "Select Generate credential, copy the client ID and the secret, then select Done."
  s_client PO connector "$REQUIRED_SCOPES"

  # ── 4. The tailnet ──
  stage "The lab tailnet"
  s_fetch "/tailnet/-/users" "$S_USERS" || die "Setup needs users:read on the admin client. Fix its scopes and run --setup again."
  s_fetch "/tailnet/-/devices?fields=all" "$S_DEVICES" || die "Setup needs devices:core:read on the admin client. Fix its scopes and run --setup again."
  s_fetch "/tailnet/-/acl" "$S_ACL" "Accept: application/json" || : >"$S_ACL"
  s_fetch "/tailnet/-/services" "$S_SERVICES" || : >"$S_SERVICES"
  local cand tries=0
  cand="$(jq -r '[.users[]?.tailnetId // empty | tostring | select(test("^T[A-Za-z0-9]+CNTRL$"))][0] // empty' "$S_USERS" 2>/dev/null || true)"
  if [[ -n "$cand" ]]; then
    say "Tailscale's user list names this tailnet's ID: $cand."
  else
    say "The API answers to \"-\" for your own tailnet but doesn't say its ID, so copy it from the console."
    open_page "$CONSOLE/settings/general"
    step "On Settings, General, copy the Tailnet ID (T...CNTRL). Not the Legacy ID, not the DNS name."
  fi
  while :; do
    tries=$((tries + 1))
    s_ask TAILNET "Tailnet ID:" "$cand"
    if dry; then
      api GET "/tailnet/$TAILNET/users" "$S_TOK" ""
      break
    fi
    if [[ -z "$TAILNET" || "$TAILNET" == *.* ]]; then
      warn "That's not a Tailnet ID. It starts with T and ends with CNTRL, with no dots."
    else
      api GET "/tailnet/$TAILNET/users" "$S_TOK" ""
      if [[ "$ST" == 200 ]]; then break; fi
      warn "Tailscale answered HTTP $ST for $TAILNET, so it isn't this client's tailnet. Copy it again from Settings, General."
    fi
    TAILNET=""
    [[ "$tries" -lt 3 ]] || die "Setup stopped: no Tailnet ID that Tailscale accepts. Run --setup again."
  done
  [[ "$TAILNET" =~ ^T[A-Za-z0-9]+CNTRL$ ]] || warn "$TAILNET works, but looks like a Legacy ID. The Tailnet ID (T...CNTRL) is preferred."
  s_put TAILNET "$TAILNET"
  if dry; then
    note "(dry run, would ask) Is $TAILNET a throwaway lab tailnet the test may edit?"
    s_put LAB_TAILNET "$TAILNET"
  elif confirm "Is $TAILNET a throwaway lab tailnet that the test may edit?"; then
    s_put LAB_TAILNET "$TAILNET"
  else
    warn "LAB_TAILNET stays blank, so the test won't start. Make a lab tailnet and run --setup again with clients from it."
  fi
  local dns
  dns="$(jq -r '[.devices[]? | select(.isExternal != true) | .name // empty][0] // empty' "$S_DEVICES" 2>/dev/null | sed -E 's/\.$//; s/^[^.]*\.//' || true)"
  if [[ -n "$dns" ]]; then
    s_put TAILNET_DNS "$dns"
  elif ! dry; then
    note "No device to read the MagicDNS domain from, so TAILNET_DNS stays blank; the test derives it later."
  fi

  # ── 5. You and device A ──
  stage "You and device A"
  s_local
  jq -r '.users[]? | select((.type // "member") != "shared") | [.loginName, "\(.loginName)  \(.displayName // "")  \(.role // "")"] | @tsv' "$S_USERS" >"$S_CHOICES" 2>/dev/null || : >"$S_CHOICES"
  say "Your Tailscale login is the requestor: the test grants it access and checks it."
  s_choose LOGIN "Your login:" "${LOGIN:-$LOCAL_LOGIN}"
  if [[ -n "$LOGIN" ]]; then s_put LOGIN "$LOGIN"; fi
  jq -r --arg l "$LOGIN" '.devices[]? | select(.isExternal != true and .user == $l and ((.tags // []) | length) == 0) | [.nodeId, "\(.name | split(".")[0])  \(.os // "")  \(.nodeId)"] | @tsv' "$S_DEVICES" >"$S_CHOICES" 2>/dev/null || : >"$S_CHOICES"
  if ! dry && [[ ! -s "$S_CHOICES" ]]; then
    warn "No untagged device is signed in as $LOGIN. Sign this machine in to the lab tailnet as $LOGIN, then run --setup again."
  fi
  say "Device A is the machine you'll run the test on."
  s_choose DEVICE_A "Device A:" "${DEVICE_A:-$LOCAL_NODE}"
  if [[ -n "$DEVICE_A" ]]; then
    s_put DEVICE_A "$DEVICE_A"
    if [[ -n "$LOCAL_NODE" && "$LOCAL_NODE" != "$DEVICE_A" ]]; then
      warn "That's not this machine ($LOCAL_NODE). Run the test on device A."
    fi
  fi

  # ── 6. Device B ──
  stage "Device B"
  jq -r --arg a "$DEVICE_A" '[.devices[]? | select(.isExternal != true and .nodeId != $a)] | sort_by(((.tags // []) | length) == 0) | .[] | [.nodeId, "\(.name | split(".")[0])  \(.os // "")  \(if ((.tags // []) | length) > 0 then (.tags | join(",")) else "untagged" end)  \(.nodeId)"] | @tsv' "$S_DEVICES" >"$S_CHOICES" 2>/dev/null || : >"$S_CHOICES"
  say "Device B is the machine the test grants access to. A tagged one is best; tagged ones are listed first."
  local want_b="$DEVICE_B" b_tags b_host owned
  if [[ -z "$want_b" ]] && head -n1 "$S_CHOICES" | grep -q 'tag:'; then want_b="$(head -n1 "$S_CHOICES" | cut -f1)"; fi
  s_choose DEVICE_B "Device B:" "$want_b"
  if [[ -n "$DEVICE_B" ]]; then s_put DEVICE_B "$DEVICE_B"; fi
  b_host="$(s_device_field "$DEVICE_B" '.name // empty' | sed 's/\.$//')"
  b_tags="$(s_device_field "$DEVICE_B" '(.tags // []) | join(" ")')"
  if [[ -n "$b_host" ]]; then
    s_put DEVICE_B_HOST "$b_host"
  else
    s_ask DEVICE_B_HOST "Device B's Tailscale IP or MagicDNS name, as you'd type it on A:"
    if [[ -n "$DEVICE_B_HOST" ]]; then s_put DEVICE_B_HOST "$DEVICE_B_HOST"; fi
  fi
  if [[ -n "$b_tags" && "$b_tags" != *" "* ]]; then
    s_put TAG_B "$b_tags"
  elif [[ -n "$b_tags" ]]; then
    printf '%s\n' $b_tags | awk '{ printf "%s\t%s\n", $1, $1 }' >"$S_CHOICES"
    s_choose TAG_B "B has several tags. Which one should the test use?" "$TAG_B"
    if [[ -n "$TAG_B" ]]; then s_put TAG_B "$TAG_B"; fi
  elif ! dry; then
    warn "B has no tag. In Machines, open B's menu, Edit ACL tags, and add one that's in the policy file's tagOwners (such as tag:spec-b)."
    s_ask TAG_B "The tag you gave B (tag:...):"
    if [[ -n "$TAG_B" ]]; then s_put TAG_B "$TAG_B"; fi
  fi
  owned="$(jq -r '[to_entries[]? | select(.key | ascii_downcase == "tagowners") | .value | keys[]] | join(" ")' "$S_ACL" 2>/dev/null || true)"
  if ! dry && [[ -n "$TAG_B" ]] && ! in_list "$TAG_B" "$owned"; then
    warn "$TAG_B isn't in the policy file's tagOwners. Add it there before the run."
  fi
  say "The test connects from A to B on a TCP port. Pick one B listens on, or start a listener on B, such as: python3 -m http.server 8080"
  note "Port 22 is taken by Tailscale SSH checks, so a separate port keeps them apart."
  s_ask PORT_B "The TCP port B listens on:" 8080
  if [[ -n "$PORT_B" ]]; then s_put PORT_B "$PORT_B"; fi
  say "Turn on Tailscale SSH on B if it isn't (on B: tailscale set --ssh)."
  s_ask SSH_USER "A local user on B to SSH in as (whoami on B), or Enter to leave it blank:"
  if [[ -n "$SSH_USER" ]]; then s_put SSH_USER "$SSH_USER"; else note "SSH_USER is blank: the test asks for it at the start."; fi

  # ── 7. A subnet router and a service ──
  stage "A subnet router and a service"
  say "Setup looks for each in the lab. Whatever isn't there stays blank, and its checks SKIP."
  local c_id route
  jq -r --arg a "$DEVICE_A" --arg b "$DEVICE_B" '.devices[]? | select(.isExternal != true) | select([(.advertisedRoutes // [])[] | select(. != "0.0.0.0/0" and . != "::/0")] | length > 0) | [.nodeId, "\(.name | split(".")[0])  \((.tags // []) | join(","))  routes \([(.advertisedRoutes // [])[] | select(. != "0.0.0.0/0" and . != "::/0")] | join(" "))"] | @tsv' "$S_DEVICES" >"$S_CHOICES" 2>/dev/null || : >"$S_CHOICES"
  c_id=""
  if dry; then
    note "(dry run, would look for) a subnet router and a service"
  elif [[ -s "$S_CHOICES" ]]; then
    say "Subnet routers:"
    s_choose c_id "Subnet router C:" "$DEVICE_C"
  else
    note "No subnet router: DEVICE_C stays blank, so A65 SKIPs."
  fi
  if [[ -n "$c_id" ]]; then
    s_put DEVICE_C "$c_id"
    route="$(s_device_field "$c_id" '[(.enabledRoutes // [])[] | select(test("^[0-9.]+/[0-9]+$") and . != "0.0.0.0/0")][0] // empty')"
    if [[ -n "$route" ]]; then s_put ROUTER_SUBNET "$route"; else note "C has no approved IPv4 route: ROUTER_SUBNET stays blank, so A65 SKIPs."; fi
  fi

  if ! dry; then
    jq -r '.vipServices[]? | [.name, "\(.name)  \((.ports // []) | map(tostring) | join(","))"] | @tsv' "$S_SERVICES" >"$S_CHOICES" 2>/dev/null || : >"$S_CHOICES"
    if [[ -s "$S_CHOICES" ]]; then
      say "Tailscale Services:"
      s_choose SERVICE_NAME "Service:" "$SERVICE_NAME"
      if [[ -n "$SERVICE_NAME" ]]; then s_put SERVICE_NAME "$SERVICE_NAME"; fi
    else
      note "No Tailscale Service: SERVICE_NAME stays blank, and A82 checks only the answer's shape."
    fi
  fi

  # ── 8. Optional extras ──
  stage "Optional extras"
  s_extras

  S_TOK=""
  forget_tokens
  if dry; then
    printf '\n  Dry run: %s calls printed, none made, nothing written.\n' "$CALLS"
  else
    finish
  fi
  s_summary
  local cmd="$0"
  if [[ "$ENV_FILE" != .env ]]; then cmd="$cmd --env-file $ENV_FILE"; fi
  printf '\n'
  say "Next, on device A:"
  step "$cmd --dry-run    (prints every call, changes nothing)"
  step "$cmd              (the full run)"
  printf '\n'
}

if [[ "$SETUP" == 1 ]]; then
  run_setup
  exit 0
fi

if ! dry && [[ -z "$TAILNET" ]]; then
  die "TAILNET is blank in $ENV_FILE. Run with --setup first: $0 --setup"
fi

# ── Stages ────────────────────────────────────────────────────────────────

SELECTED_AREAS=""
for area in $AREAS; do
  for ((i = 0; i < ${#C_IDS[@]}; i++)); do
    if [[ "${C_AREAS[$i]}" == "$area" ]] && is_selected "$i"; then
      SELECTED_AREAS="$SELECTED_AREAS $area"
      break
    fi
  done
done
TOTAL_STAGES=$(($(printf '%s\n' $SELECTED_AREAS | grep -c .) + 2))

if dry; then
  # A dry run prints everything in one scroll.
  _clear() { :; }
  printf '\n%s%s  Tailscale spec test (INT-666), dry run%s\n' "$BOLD" "$BLUE" "$RESET"
  note "No call is made, nothing is asked or written. Placeholders fill any missing input."
else
  banner "Tailscale spec test (INT-666)"
fi

# ── Stage: lab and inputs ─────────────────────────────────────────────────
stage "Lab tailnet and inputs"
if ! dry; then
  mkdir -p "$OUT_DIR"
  # The env file holds only IDs (secrets are read hidden), so it may sit in a
  # checkout; the warning is there so it isn't committed by accident.
  if git -C "$OUT_DIR" rev-parse --is-inside-work-tree >/dev/null 2>&1 && ! git -C "$OUT_DIR" check-ignore -q "$ENV_FILE" 2>/dev/null; then
    warn "$ENV_FILE is inside a git checkout and not ignored. Don't commit it."
  fi
  if [[ ! -f "$ENV_FILE" ]]; then
    cp "$SCRIPT_DIR/admin-test.env.example" "$ENV_FILE"
    chmod 600 "$ENV_FILE"
    say "Created $ENV_FILE from admin-test.env.example."
  fi
  say "Inputs: $ENV_FILE (secrets are never read from or written to it)."
  if [[ -z "$LAB_TAILNET" ]]; then
    die "LAB_TAILNET is blank in $ENV_FILE. Run with --setup first, and confirm there that $TAILNET is a lab tailnet. This test refuses to start without it."
  fi
  if [[ "$TAILNET" != "$LAB_TAILNET" ]]; then
    die "TAILNET ($TAILNET) isn't LAB_TAILNET ($LAB_TAILNET). This test runs only against the lab tailnet."
  fi
  warn "This run writes $TAILNET's policy file and device attributes, and undoes every change."
  printf '  %sType the Tailnet ID again to confirm it is a throwaway lab tailnet:%s ' "$BOLD" "$RESET"
  if [[ -n "$CONFIRM_LAB" ]]; then
    typed="$CONFIRM_LAB"
    printf '%s (from --confirm-lab)\n' "$typed"
  else
    read -r typed || true
  fi
  [[ "$typed" == "$TAILNET" ]] || die "Not confirmed. Nothing was changed."
  missing_core=""
  for key in LOGIN DEVICE_A DEVICE_B DEVICE_B_HOST TAG_B PORT_B SSH_USER ADMIN_CLIENT_ID PO_CLIENT_ID; do
    [[ -n "${!key}" ]] || missing_core="$missing_core $key"
  done
  if [[ -n "$missing_core" ]]; then
    open_url "$CONSOLE/machines"
    step "Device A is this machine, signed in as the requestor, untagged. Device B is tagged, runs Tailscale SSH and listens on a TCP port."
    step "A node ID (n...CNTRL) is in each machine's details; client IDs are in Settings > Trust credentials."
    for key in $missing_core; do
      case "$key" in
        LOGIN) ask LOGIN "The requestor's login name, as on the Users page:" ;;
        DEVICE_A) ask DEVICE_A "Device A's node ID:" ;;
        DEVICE_B) ask DEVICE_B "Device B's node ID:" ;;
        DEVICE_B_HOST) ask DEVICE_B_HOST "Device B's Tailscale IP or MagicDNS name:" ;;
        TAG_B) ask TAG_B "Device B's tag (tag:...):" ;;
        PORT_B) ask PORT_B "The TCP port B listens on:" ;;
        SSH_USER) ask SSH_USER "A user to SSH into B as:" ;;
        ADMIN_CLIENT_ID) ask ADMIN_CLIENT_ID "The admin OAuth client's ID:" ;;
        PO_CLIENT_ID) ask PO_CLIENT_ID "The connector's OAuth client's ID:" ;;
      esac
      write_env "$key" "${!key}"
    done
  fi
  : >"$LOG"
  chmod 600 "$LOG"
fi
quote_inputs
extras=""
for key in RO_CLIENT_ID ALL_CLIENT_ID FED_AWS_CLIENT_ID FED_GCP_CLIENT_ID SHARED_DEVICE FREE_TAILNET SPARE_DEVICE DEVICE_C SERVICE_NAME; do
  [[ -n "${!key}" ]] && extras="$extras $key"
done
say "Tailnet $TAILNET, run $RID. Everything it adds is named after the run: $PST, $KEY."
note "Optional extras set:${extras:- none} (the rest skip)."
note "Areas:$SELECTED_AREAS"
dry || pause "Press Enter to start the checks."

# ── Stages: one per area ──────────────────────────────────────────────────
for area in $SELECTED_AREAS; do
  stage "$(area_title "$area")"
  for ((i = 0; i < ${#C_IDS[@]}; i++)); do
    if [[ "${C_AREAS[$i]}" == "$area" ]] && is_selected "$i"; then
      run_check "$i"
    fi
  done
  printf '\n'
  dry || pause "Press Enter for the next stage."
done

# ── Stage: results ────────────────────────────────────────────────────────
stage "Results"
for id in A07 A21 A22 A25 A26 A28; do
  if in_list "$id" "$DEFERRED"; then
    CUR_ID="$id"
    printf '\n  %s%s%s %s\n' "$BOLD" "$id" "$RESET" "${C_CLAIMS[$(idx_of "$id")]}"
    "finish_$id" || true
    has_result "$id" || res "$id" FAIL "no verdict"
  fi
done
settle
write_results
ADMIN_SECRET=""
PO_SECRET=""

finish
print_table
if dry; then
  printf '\n  Dry run: %s calls printed, none made.\n\n' "$CALLS"
else
  printf '\n  Results: %s\n  Call log (redacted): %s\n  Paste the results into INT-666.\n\n' "$RESULTS" "$LOG"
fi
